-- ===== 20261006000015_admin_matrix.sql =====
-- Patch B14 / migration 15 — the Admin "My Teams" live control matrix (READ side only) and member presence.
--
-- What this migration adds
--   * app.presence_timeout_seconds()  the ONE definition of "how long without a sign of life before a member is OUT" (75 s).
--   * member_presence (view)          re-declared on that constant and now also requires the session not to be expired.
--   * public.admin_matrix(staff)      one row per team the Admin OWNS: M1..M4 presence, the ten A..J theme cells, Final Submit.
--   * public.admin_team_theme(...)    the five-question drill-down of one theme cell, with the pending submission (if any).
--   * drops public.list_pending_submissions (the temporary B13 review queue, replaced by the matrix drill-down).
--
-- What it deliberately does NOT touch: create_team / list_admin_teams / team ownership (B12), approve_submission /
-- disapprove_submission and every other mutation (B13), coins, scoring, timers, the competition structure. Reward amounts
-- stay question-level data (questions.reward_coins, seeded to 50): approve_submission already pays exactly that column.
--
-- Both new functions are pure reads (STABLE, no writes, no audit). Ownership is enforced HERE, in the database: the staff
-- id comes from the session, a team the caller does not own is NOT_FOUND (indistinguishable from an unknown id), and a
-- Super Admin gets FORBIDDEN exactly as list_admin_teams does (the matrix is the Admin's own board).
-- No reference answer or solution note is ever selected (question_keys is not read by any function in this file).

-- ---------------------------------------------------------------------------------------------------------------
-- Presence. "Authenticated" and "online" are different: a live session proves the member signed in, `last_seen_at`
-- proves the browser is still talking to us. It is refreshed by every authenticated request (resolve_session) and by the
-- participant heartbeat (POST /api/p/heartbeat, every 25 s, even from a hidden tab). A member is ONLINE while their live,
-- unexpired session was seen within the timeout. Logout revokes the session, so OUT is immediate; a closed browser or a
-- lost network goes OUT when the timeout runs out; any request after that makes them ONLINE again.
-- ---------------------------------------------------------------------------------------------------------------
create function app.presence_timeout_seconds() returns int
language sql immutable
as $$ select 75 $$;

create or replace view member_presence with (security_invoker = true) as
select m.id as member_id, m.team_id, m.slot,
       (case when exists (select 1 from sessions s
                           where s.member_id = m.id and s.revoked_at is null
                             and s.expires_at > app.now()
                             and s.last_seen_at > app.now() - make_interval(secs => app.presence_timeout_seconds()))
             then 'ONLINE' else 'OFFLINE' end)::presence_state as presence
from team_members m;

-- ---------------------------------------------------------------------------------------------------------------
-- app.require_owner_admin: the caller must be an active ADMIN who owns the team. Anything else is an error that does
-- not reveal whether the team exists.
-- ---------------------------------------------------------------------------------------------------------------
create function app.require_owner_admin(p_staff_id uuid, p_team_id uuid) returns void
language plpgsql stable
set search_path = pg_catalog, public, app, pg_temp
as $$
begin
  if p_staff_id is null or not exists (select 1 from staff_users where id = p_staff_id and role = 'ADMIN' and is_active) then
    perform app.fail('FORBIDDEN');
  end if;
  if p_team_id is null or not exists (select 1 from teams where id = p_team_id and admin_id = p_staff_id) then
    perform app.fail('NOT_FOUND');
  end if;
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- admin_matrix(staff_id)
--   { server_now, presence_timeout_seconds,
--     teams: [ { id, team_code, name, status, final_submitted,
--                members: [ { slot, presence } ] (always M1..M4 that exist),
--                themes:  [ { code, state: NORMAL|RED|GREEN, approved, pending } ] (always A..J, in order) } ] }
--   RED   = at least one question of the theme is PENDING_APPROVAL (the Admin has something to review)
--   GREEN = all five questions are APPROVED
--   NORMAL otherwise (an unlocked theme with nothing pending is NOT red)
-- ---------------------------------------------------------------------------------------------------------------
create function public.admin_matrix(p_staff_id uuid) returns jsonb
language plpgsql stable security definer
set search_path = pg_catalog, public, extensions, app, pg_temp
as $$
begin
  if p_staff_id is null or not exists (select 1 from staff_users where id = p_staff_id and role = 'ADMIN' and is_active) then
    perform app.fail('FORBIDDEN');
  end if;
  return jsonb_build_object(
    'server_now', app.epoch_ms(app.now()),
    'presence_timeout_seconds', app.presence_timeout_seconds(),
    'teams', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', t.id,
               'team_code', t.team_code,
               'name', t.name,
               'status', t.status::text,
               'final_submitted', (t.status = 'FINAL_SUBMITTED'),
               'members', (select coalesce(jsonb_agg(jsonb_build_object('slot', p.slot, 'presence', p.presence::text)
                                                      order by p.slot), '[]'::jsonb)
                             from member_presence p where p.team_id = t.id),
               'themes', (select jsonb_agg(jsonb_build_object(
                                    'code', th.code,
                                    'state', case when c.pending > 0 then 'RED'
                                                  when c.approved = 5 then 'GREEN'
                                                  else 'NORMAL' end,
                                    'approved', c.approved,
                                    'pending', c.pending) order by th.id)
                            from themes th
                            cross join lateral (
                              select count(*) filter (where tq.state = 'APPROVED')         as approved,
                                     count(*) filter (where tq.state = 'PENDING_APPROVAL') as pending
                                from team_questions tq
                               where tq.team_id = t.id and tq.theme_id = th.id) c)
             ) order by t.created_at, t.team_code)
        from teams t where t.admin_id = p_staff_id), '[]'::jsonb));
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- admin_team_theme(staff_id, team_id, theme_code)
--   { server_now, team: {id, team_code, name}, theme: {code, name},
--     questions: [ { id, ordinal, label ("D.2"), color: WHITE|RED|GREEN, state, submission: null | {...} } ] }
--   color  GREEN = APPROVED, RED = PENDING_APPROVAL, WHITE = anything else (locked, available, active, timed out)
--   state  the raw question state, for the label ("Active", "Locked", ...). A theme the team has not unlocked has no
--          team_questions rows: its five questions are reported LOCKED.
--   submission  only for a RED question: the PENDING submission (answer, explanation, who, when) and the question text,
--          i.e. exactly what the existing approve/disapprove endpoints act on. NEVER a reference answer or key.
-- ---------------------------------------------------------------------------------------------------------------
create function public.admin_team_theme(p_staff_id uuid, p_team_id uuid, p_theme_code text) returns jsonb
language plpgsql stable security definer
set search_path = pg_catalog, public, extensions, app, pg_temp
as $$
declare
  v_team  teams%rowtype;
  v_theme themes%rowtype;
begin
  perform app.require_owner_admin(p_staff_id, p_team_id);
  select * into v_team from teams where id = p_team_id;
  select * into v_theme from themes where code = upper(btrim(coalesce(p_theme_code, '')));
  if not found then
    perform app.fail('NOT_FOUND');
  end if;

  return jsonb_build_object(
    'server_now', app.epoch_ms(app.now()),
    'team', jsonb_build_object('id', v_team.id, 'team_code', v_team.team_code, 'name', v_team.name),
    'theme', jsonb_build_object('code', v_theme.code, 'name', v_theme.name),
    'questions', (
      select jsonb_agg(jsonb_build_object(
               'id', q.id,
               'ordinal', q.ordinal,
               'label', v_theme.code || '.' || q.ordinal,
               'color', case tq.state::text when 'APPROVED' then 'GREEN'
                                            when 'PENDING_APPROVAL' then 'RED'
                                            else 'WHITE' end,
               'state', coalesce(tq.state::text, 'LOCKED'),
               'submission', case when tq.state = 'PENDING_APPROVAL' then
                   (select jsonb_build_object(
                             'id', sub.id,
                             'body_md', q.body_md,
                             'answer', sub.answer,
                             'explanation', sub.explanation,
                             'submitted_by_slot', m.slot,
                             'submitted_at', app.epoch_ms(sub.submitted_at),
                             'reward_coins', q.reward_coins)
                      from submissions sub
                      left join team_members m on m.id = sub.member_id
                     where sub.team_id = tq.team_id and sub.question_id = tq.question_id and sub.status = 'PENDING')
                 end) order by q.ordinal)
        from questions q
        left join team_questions tq on tq.team_id = p_team_id and tq.question_id = q.id
       where q.theme_id = v_theme.id));
end $$;

-- The temporary B13 review queue is replaced by the matrix drill-down; nothing else uses it.
drop function public.list_pending_submissions(uuid);

revoke all on function app.presence_timeout_seconds()                         from public, anon, authenticated;
revoke all on function app.require_owner_admin(uuid, uuid)                    from public, anon, authenticated;
revoke all on function public.admin_matrix(uuid)                              from public, anon, authenticated;
revoke all on function public.admin_team_theme(uuid, uuid, text)              from public, anon, authenticated;

grant execute on function app.presence_timeout_seconds()                      to service_role;
grant execute on function app.require_owner_admin(uuid, uuid)                 to service_role;
grant execute on function public.admin_matrix(uuid)                           to service_role;
grant execute on function public.admin_team_theme(uuid, uuid, text)          to service_role;

-- ===== 20261006000016_timer_14400_and_finalization.sql =====
-- Patch B15 / migration 16 — the 4-hour Ultimate Team Timer, a per-team allowance snapshot, and persisted
-- auto-finalization at zero.
--
-- Why it is safe for teams that are already playing: the competition-wide value (`competition.ultimate_seconds`) is only
-- READ when a team STARTS (start_team_competition). A team that has already started keeps the absolute `started_at` /
-- `ends_at` it was given, so changing the value changes nothing for it. This migration never writes `started_at`,
-- `ends_at`, `ended_at`, `coins` or `status` of any team. The only column it fills on a started team is the new
-- `teams.timer_seconds` (= 7200, the allowance that team actually received); `updated_at` follows via the existing
-- touch trigger. Teams that have not started yet get 14400 s when they first enter. No team is ever extended.
--
-- Contents
--   1. competition.ultimate_seconds: 7200 -> 14400 (default, the row, the locking CHECK).
--   2. teams.timer_seconds: the allowance a team was given when it started (NULL until it starts).
--   3. teams.final_minutes_taken: the 0..120 upper bound belonged to the 2 h timer; scoring (B16) owns the rounding.
--   4. start_team_competition (re-declared): also stores timer_seconds.
--   5. app.team_state_json (re-declared): per-team duration_seconds and the `frozen` flag.
--   6. finalize_team_if_due / expire_due_teams: the persisted RUNNING -> ENDED transition at zero. No pg_cron needed.
--   7. State versions of NOT_STARTED teams (their snapshot duration changed) and one SYSTEM audit row.
--
-- Everything else (lock order, idempotency, error codes, privileges) follows the B10/B13 conventions.

-- ---------------------------------------------------------------------------------------------------------------
-- 1. The competition-wide allowance for teams that start from now on
-- ---------------------------------------------------------------------------------------------------------------
alter table competition drop constraint competition_ultimate_locked_7200;
alter table competition alter column ultimate_seconds set default 14400;
update competition set ultimate_seconds = 14400 where id = 1;          -- ultimate_minutes (generated) becomes 240
alter table competition add constraint competition_ultimate_locked_14400 check (ultimate_seconds = 14400);

-- ---------------------------------------------------------------------------------------------------------------
-- 2. The per-team snapshot. Teams that started under the 2 h rule keep exactly that allowance.
-- ---------------------------------------------------------------------------------------------------------------
alter table teams add column timer_seconds int;
update teams set timer_seconds = 7200 where started_at is not null;     -- the allowance every pre-B15 team was given
alter table teams add constraint teams_timer_seconds_iff_started
  check ((timer_seconds is not null) = (started_at is not null) and (timer_seconds is null or timer_seconds > 0));
comment on column teams.timer_seconds is
  'Ultimate Team Timer allowance in seconds, copied from competition.ultimate_seconds when the team started '
  '(7200 for teams that started before B15, 14400 afterwards). NULL until the team starts. Never edited afterwards.';

-- ---------------------------------------------------------------------------------------------------------------
-- 3. final_minutes_taken: a 4 h team can legitimately exceed 120. Scoring (B16) computes and rounds it.
-- ---------------------------------------------------------------------------------------------------------------
alter table teams drop constraint teams_final_minutes_taken_check;
alter table teams add constraint teams_final_minutes_taken_nonneg
  check (final_minutes_taken is null or final_minutes_taken >= 0);

-- ---------------------------------------------------------------------------------------------------------------
-- 4. start_team_competition — unchanged apart from storing the allowance in teams.timer_seconds.
-- ---------------------------------------------------------------------------------------------------------------
create or replace function public.start_team_competition(p_team_id uuid, p_member_id uuid, p_idem_key uuid) returns jsonb
language plpgsql security definer
set search_path = pg_catalog, public, extensions, app, pg_temp
as $$
declare
  v_now     timestamptz;
  v_team    teams%rowtype;
  v_comp    competition%rowtype;
  v_fp      text := 'member:' || coalesce(p_member_id::text, '');
  v_replay  jsonb;
  v_started boolean := false;
  v_resp    jsonb;
begin
  if p_team_id is null or p_member_id is null
     or not exists (select 1 from team_members where id = p_member_id and team_id = p_team_id) then
    perform app.fail('FORBIDDEN');                                     -- a member can only act for their own team
  end if;
  if p_idem_key is null then
    perform app.fail('VALIDATION_FAILED', jsonb_build_object('fields', jsonb_build_array('idempotencyKey')));
  end if;

  v_team := app.lock_team(p_team_id);                                  -- competition (share) → team (update)

  v_replay := app.idem_lookup(p_team_id, p_idem_key, 'start_team_competition', v_fp);
  if v_replay is not null then
    return v_replay || '{"replayed": true}'::jsonb;
  end if;

  select * into v_comp from competition where id = 1;

  if v_team.status <> 'RUNNING' then
    if v_comp.id is null or v_comp.status in ('SETUP', 'ENDED') then
      perform app.fail('COMPETITION_NOT_RUNNING');
    elsif v_comp.status = 'PAUSED' then
      perform app.fail('COMPETITION_PAUSED');
    end if;
    if v_team.status = 'FINAL_SUBMITTED' then
      perform app.fail('ALREADY_SUBMITTED');
    elsif v_team.status <> 'NOT_STARTED' then
      perform app.fail('TEAM_ENDED');                                  -- ENDED or DISQUALIFIED
    end if;

    v_now := app.now();
    update teams
       set status = 'RUNNING',
           started_at = v_now,
           ends_at = v_now + make_interval(secs => v_comp.ultimate_seconds),
           timer_seconds = v_comp.ultimate_seconds,                    -- B15: the allowance this team was given
           state_version = state_version + 1
     where id = p_team_id;

    insert into audit_events (occurred_at, actor_kind, member_id, team_id, event_type, entity_type, entity_id, payload, request_id)
    values (v_now, 'MEMBER', p_member_id, p_team_id, 'TEAM_STARTED', 'TEAM', p_team_id::text,
            jsonb_build_object('started_at', app.epoch_ms(v_now),
                               'ends_at', app.epoch_ms(v_now + make_interval(secs => v_comp.ultimate_seconds)),
                               'ultimate_seconds', v_comp.ultimate_seconds),
            p_idem_key);
    v_started := true;
  end if;

  v_resp := jsonb_build_object('replayed', false, 'started_now', v_started,
                               'state', app.team_state_json(p_team_id, p_member_id));
  perform app.idem_store(p_team_id, p_idem_key, 'start_team_competition', v_fp, v_resp);
  return v_resp;
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- 5. app.team_state_json — B13 body, with two changes only:
--      * team.duration_seconds is the TEAM's own allowance (teams.timer_seconds, falling back to the competition value
--        for a team that has not started), so a team that started under the 2 h rule keeps reporting 7200;
--      * team.frozen: true once the team can no longer play (FINAL_SUBMITTED / ENDED / DISQUALIFIED, or the timer ran out
--        and the ENDED row has not been written yet). A pause is NOT "frozen" (it is a competition status).
-- Still a pure read.
-- ---------------------------------------------------------------------------------------------------------------
create or replace function app.team_state_json(p_team_id uuid, p_member_id uuid) returns jsonb
language plpgsql stable
set search_path = pg_catalog, public, app, pg_temp
as $$
declare
  v_now    timestamptz := app.now();
  t        teams%rowtype;
  c        competition%rowtype;
  m        team_members%rowtype;
  v_ref    timestamptz;
  v_qref   timestamptz;
  v_rem    int;
  v_themes jsonb;
  v_expired boolean;
begin
  select * into t from teams where id = p_team_id;
  select * into c from competition where id = 1;
  select * into m from team_members where id = p_member_id and team_id = p_team_id;
  if t.id is null or m.id is null or c.id is null then
    perform app.fail('NOT_FOUND');
  end if;

  v_ref := app.team_clock(t);
  v_qref := app.question_clock(t);
  v_rem := case when t.ends_at is null then c.ultimate_seconds
                else greatest(0, floor(extract(epoch from (t.ends_at - v_ref))))::int end;
  v_expired := (t.status = 'RUNNING' and v_ref >= t.ends_at);

  select coalesce(jsonb_agg(
           jsonb_build_object(
             'id', th.id,
             'code', th.code,
             'name', th.name,
             'description', th.description,
             'topics', to_jsonb(th.topics),
             'difficulty', th.difficulty,
             'unlock_cost', th.unlock_cost,
             'status', case when tt.theme_id is null then 'LOCKED'
                            when coalesce(p.timed_out, false) then 'FAILED'
                            when coalesce(p.completed, false) then 'COMPLETED'
                            else 'IN_PROGRESS' end,
             'questions', coalesce(qs.arr, '[]'::jsonb))
           order by th.display_order), '[]'::jsonb)
    into v_themes
    from themes th
    left join team_themes tt on tt.team_id = p_team_id and tt.theme_id = th.id
    left join lateral (
      select count(*) filter (where q.state = 'APPROVED') = 5 as completed,
             bool_or(q.state = 'TIMED_OUT' or (q.state = 'ACTIVE' and q.timer_deadline <= v_qref)) as timed_out
        from team_questions q
       where q.team_id = p_team_id and q.theme_id = th.id) p on true
    left join lateral (
      select jsonb_agg(
               jsonb_build_object('id', q.question_id, 'ordinal', q.ordinal, 'state', e.state)
               || case when e.state <> 'LOCKED'
                       then jsonb_build_object('reward_coins', qq.reward_coins,
                                               'time_limit_seconds', qq.time_limit_seconds)
                       else '{}'::jsonb end
               || case when e.state = 'ACTIVE'
                       then jsonb_build_object('deadline', app.epoch_ms(q.timer_deadline),
                                               'remaining_seconds',
                                               greatest(0, floor(extract(epoch from (q.timer_deadline - v_qref))))::int)
                       when e.state = 'PENDING_APPROVAL'
                       then jsonb_build_object('remaining_seconds', q.timer_remaining_seconds)
                       else '{}'::jsonb end
               order by q.ordinal) as arr
        from team_questions q
        join questions qq on qq.id = q.question_id
        cross join lateral (select case when q.state = 'ACTIVE' and q.timer_deadline <= v_qref
                                        then 'TIMED_OUT' else q.state::text end as state) e
       where q.team_id = p_team_id and q.theme_id = th.id) qs on true;

  return jsonb_build_object(
    'server_now', app.epoch_ms(v_now),
    'state_version', t.state_version,
    'competition', jsonb_build_object('status', c.status),
    'me', jsonb_build_object('member_id', m.id, 'slot', m.slot, 'team_id', t.id,
                             'team_code', t.team_code, 'team_name', t.name),
    'team', jsonb_build_object(
      'status', t.status,
      'coins', t.coins,
      'started_at', app.epoch_ms(t.started_at),
      'ends_at', app.epoch_ms(t.ends_at),
      'ended_at', app.epoch_ms(t.ended_at),
      'final_submitted_at', app.epoch_ms(t.final_submitted_at),
      'duration_seconds', coalesce(t.timer_seconds, c.ultimate_seconds),
      'remaining_seconds', v_rem,
      'expired', v_expired,
      'frozen', (t.status in ('FINAL_SUBMITTED', 'ENDED', 'DISQUALIFIED') or v_expired)),
    'themes', v_themes);
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- 6. Persisted auto-finalization at zero (RUNNING -> ENDED). The rule "nothing succeeds at or after ends_at" is already
-- enforced on every request by app.assert_playable; these functions only WRITE the transition, so the stored status
-- catches up with what every read already reports. They do not depend on pg_cron: the API calls
-- finalize_team_if_due whenever anyone on a team loads its state, and expire_due_teams is a safety net that a scheduler
-- (a Vercel Cron route today) may call.
--
--   * ended_at = the team's own ends_at (NOT the moment the function happens to run), so the result is the same whenever
--     and however it is processed. Already-overdue ACTIVE questions become TIMED_OUT (app.expire_team); a question whose
--     own deadline is still later stays ACTIVE and is shown frozen. Coins, ledger and submissions are not touched.
--   * Only while the competition is RUNNING. During a pause nothing is due; `resume` / `end` already end such teams.
--   * Idempotent and non-raising: a team that is not due (or already terminal) returns finalized:false and changes nothing.
--   * Lock order is the global one: competition (share) -> team (update). expire_due_teams uses SKIP LOCKED, so it never
--     queues behind a live participant request.
-- ---------------------------------------------------------------------------------------------------------------
create function public.finalize_team_if_due(p_team_id uuid) returns jsonb
language plpgsql security definer
set search_path = pg_catalog, public, extensions, app, pg_temp
as $$
declare
  v_team teams%rowtype;
  v_comp competition%rowtype;
begin
  v_team := app.lock_team(p_team_id);                                  -- NOT_FOUND for an unknown team
  select * into v_comp from competition where id = 1;
  if v_comp.status = 'RUNNING' and v_team.status = 'RUNNING' and app.now() >= v_team.ends_at then
    perform app.expire_team(p_team_id, 'TIMER', v_team.ends_at);
    update teams set state_version = state_version + 1 where id = p_team_id;
    return jsonb_build_object('finalized', true, 'status', 'ENDED');
  end if;
  return jsonb_build_object('finalized', false, 'status', v_team.status);
end $$;

create function public.expire_due_teams(p_limit int default 200) returns int
language plpgsql security definer
set search_path = pg_catalog, public, extensions, app, pg_temp
as $$
declare
  v_comp competition%rowtype;
  v_n    int := 0;
  r      record;
begin
  if p_limit is null or p_limit < 1 or p_limit > 1000 then
    perform app.fail('VALIDATION_FAILED', jsonb_build_object('fields', jsonb_build_array('limit')));
  end if;
  select * into v_comp from competition where id = 1 for share;        -- competition first, then teams
  if not found or v_comp.status <> 'RUNNING' then
    return 0;
  end if;
  for r in
    select id, ends_at from teams
     where status = 'RUNNING' and ends_at <= app.now()
     order by ends_at, id
     limit p_limit
       for update skip locked
  loop
    perform app.expire_team(r.id, 'TIMER', r.ends_at);
    update teams set state_version = state_version + 1 where id = r.id;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

-- explicit for the two re-declared functions as well (CREATE OR REPLACE keeps their old privileges; stating them again
-- makes this file self-describing and idempotent)
revoke all on function public.start_team_competition(uuid, uuid, uuid) from public, anon, authenticated;
revoke all on function app.team_state_json(uuid, uuid)                 from public, anon, authenticated;
revoke all on function public.finalize_team_if_due(uuid)               from public, anon, authenticated;
revoke all on function public.expire_due_teams(int)                    from public, anon, authenticated;
grant execute on function public.start_team_competition(uuid, uuid, uuid) to service_role;
grant execute on function app.team_state_json(uuid, uuid)                 to service_role;
grant execute on function public.finalize_team_if_due(uuid)               to service_role;
grant execute on function public.expire_due_teams(int)                    to service_role;

-- ---------------------------------------------------------------------------------------------------------------
-- 7. Teams that have not started: their snapshot's duration_seconds just changed (7200 -> 14400), so clients holding an
-- older snapshot should adopt the new one. Started teams are NOT written (their snapshot content is unchanged).
-- One SYSTEM audit row records the change and what it did NOT touch.
-- ---------------------------------------------------------------------------------------------------------------
update teams set state_version = state_version + 1 where status = 'NOT_STARTED';

insert into audit_events (occurred_at, actor_kind, event_type, entity_type, entity_id, payload)
select app.now(), 'SYSTEM', 'TIMER_CONFIG_CHANGED', 'COMPETITION', '1',
       jsonb_build_object('from_seconds', 7200, 'to_seconds', 14400,
                          'started_teams_kept_at_7200', (select count(*) from teams where timer_seconds = 7200),
                          'not_started_teams', (select count(*) from teams where status = 'NOT_STARTED'))
 where exists (select 1 from competition where id = 1);          -- a fresh database has no competition row yet

-- ===== 20261006000017_economy_and_final_submit.sql =====
-- Patch B15 / migration 17 — real Hint purchases, real Buy Time, Final Submit with a terminal freeze.
--
-- Three new participant operations, all built on the B10/B13 engine exactly as unlock_theme is:
--     assert_member -> key present -> app.lock_team (competition share -> team update) -> idem_lookup -> assert_playable
--     -> settle_questions -> validate -> balance check -> coins + ledger + purchase row + state_version -> audit -> idem_store
--   * buy_hint(team, member, question, tier, key)
--   * buy_time(team, member, question, option, expected_purchase_count, key)
--   * final_submit(team, member, confirm, key)
-- Any rejection RAISES (P0001 + stable code), which rolls back every write, so there is never a partial charge.
--
-- Prices, rewards and durations are DATA: a hint costs hints.cost, a Buy Time option adds question_buy_time_options.seconds
-- for question_buy_time_options.cost. Nothing below contains 20, 40, 80, 100 or 50. Each purchase row stores the price
-- actually paid, so later content edits never rewrite history.
--
-- Also here:
--   * app.question_json (re-declared, additive): `hints` (cost, owned, purchasable, and body_md ONLY once the team owns it)
--     and `buy_time` (purchase_count, extra_seconds, can_buy, options). Nothing else in it changes.
--   * public.disapprove_submission (re-declared): the only change is the deadline given back to a question when the
--     team can no longer play. It was `now + frozen remaining`; on a frozen team the clock reads the team's end, so it
--     would have shown far more time than the question had when it was frozen. It is now `question clock + frozen remaining`
--     (identical to before for a live team, where the question clock is `now`).
--
-- Privileges: explicit REVOKE from PUBLIC/anon/authenticated and GRANT to service_role for every function.

-- ---------------------------------------------------------------------------------------------------------------
-- app.question_json — B13 body plus `hints` and `buy_time`. Participant-safe by construction (never question_keys, only
-- the team's own rows). A hint's text is included ONLY when this team has bought it; the price is always shown.
--   hints[]   { tier, cost, owned, purchasable, body_md? }       purchasable = the team can buy it right now
--   buy_time  { purchase_count, extra_seconds, can_buy, options: [{ id, seconds, cost, max_purchases, purchased,
--               remaining_purchases }] }                          options are listed only while the question is ACTIVE
-- ---------------------------------------------------------------------------------------------------------------
create or replace function app.question_json(p_team_id uuid, p_question_id smallint) returns jsonb
language plpgsql stable
set search_path = pg_catalog, public, app, pg_temp
as $$
declare
  t      teams%rowtype;
  qq     questions%rowtype;
  tq     team_questions%rowtype;
  v_qref timestamptz;
  v_state text;
  v_out  jsonb;
  d      answer_drafts%rowtype;
  s      submissions%rowtype;
  v_slot smallint;
  v_live boolean;
  v_has_t1 boolean;
  v_hints jsonb;
  v_buy  jsonb;
begin
  select * into t from teams where id = p_team_id;
  select * into qq from questions where id = p_question_id;
  if t.id is null or qq.id is null then
    perform app.fail('NOT_FOUND');
  end if;
  select * into tq from team_questions where team_id = p_team_id and question_id = p_question_id;
  if not found then
    perform app.fail(case when exists (select 1 from team_themes where team_id = p_team_id and theme_id = qq.theme_id)
                          then 'NOT_FOUND' else 'THEME_LOCKED' end);
  end if;

  v_qref := app.question_clock(t);
  v_state := case when tq.state = 'ACTIVE' and tq.timer_deadline <= v_qref then 'TIMED_OUT' else tq.state::text end;
  if v_state = 'LOCKED' then
    perform app.fail('QUESTION_NOT_ACTIVE');
  end if;

  -- can the team spend right now? (competition running, team running, its own timer not yet at zero)
  v_live := (select c.status = 'RUNNING' from competition c where c.id = 1)
            and t.status = 'RUNNING' and app.now() < t.ends_at;

  v_has_t1 := exists (select 1 from hint_purchases p join hints h on h.id = p.hint_id
                       where p.team_id = p_team_id and h.question_id = p_question_id and h.tier = 1);
  select coalesce(jsonb_agg(
           jsonb_build_object(
             'tier', h.tier,
             'cost', h.cost,
             'owned', hp.hint_id is not null,
             'purchasable', v_live and v_state in ('ACTIVE', 'PENDING_APPROVAL', 'APPROVED')
                            and hp.hint_id is null and (h.tier = 1 or v_has_t1))
           || case when hp.hint_id is not null then jsonb_build_object('body_md', h.body_md) else '{}'::jsonb end
           order by h.tier), '[]'::jsonb)
    into v_hints
    from hints h
    left join hint_purchases hp on hp.hint_id = h.id and hp.team_id = p_team_id
   where h.question_id = p_question_id;

  v_buy := jsonb_build_object('purchase_count', tq.time_purchase_count, 'extra_seconds', tq.extra_seconds,
                              'can_buy', v_live and v_state = 'ACTIVE', 'options', '[]'::jsonb);
  if v_state = 'ACTIVE' then
    select jsonb_set(v_buy, '{options}', coalesce(jsonb_agg(
             jsonb_build_object(
               'id', o.id, 'seconds', o.seconds, 'cost', o.cost, 'max_purchases', o.max_purchases,
               'purchased', coalesce(u.n, 0),
               'remaining_purchases', case when o.max_purchases is null then null
                                           else greatest(o.max_purchases - coalesce(u.n, 0), 0) end)
             order by o.display_order), '[]'::jsonb))
      into v_buy
      from question_buy_time_options o
      left join lateral (select count(*)::int as n from team_time_purchases x
                          where x.team_id = p_team_id and x.question_id = p_question_id and x.option_id = o.id) u on true
     where o.question_id = p_question_id;
  end if;

  v_out := jsonb_build_object(
    'id', qq.id,
    'theme_id', qq.theme_id,
    'theme_code', (select code from themes where id = qq.theme_id),
    'ordinal', qq.ordinal,
    'state', v_state,
    'reward_coins', qq.reward_coins,
    'time_limit_seconds', qq.time_limit_seconds,
    'hints', v_hints,
    'buy_time', v_buy);

  if v_state = 'AVAILABLE' then
    return v_out;                                     -- metadata only: the body is withheld until the team enters
  end if;

  v_out := v_out || jsonb_build_object('body_md', qq.body_md);
  if v_state = 'ACTIVE' then
    v_out := v_out || jsonb_build_object(
      'deadline', app.epoch_ms(tq.timer_deadline),
      'remaining_seconds', greatest(0, floor(extract(epoch from (tq.timer_deadline - v_qref))))::int);
  elsif v_state = 'PENDING_APPROVAL' then
    v_out := v_out || jsonb_build_object('remaining_seconds', tq.timer_remaining_seconds);
  end if;

  select * into d from answer_drafts where team_id = p_team_id and question_id = p_question_id;
  select slot into v_slot from team_members where id = d.updated_by;
  v_out := v_out || jsonb_build_object('draft', jsonb_build_object(
    'answer', coalesce(d.answer, ''), 'explanation', coalesce(d.explanation, ''),
    'version', coalesce(d.version, 0), 'updated_by_slot', v_slot,
    'updated_at', app.epoch_ms(d.updated_at)));

  -- the team's own live submission (pending, or the approved one); never another team's, never a reviewer key
  select * into s from submissions
   where team_id = p_team_id and question_id = p_question_id and status in ('PENDING', 'APPROVED')
   order by submitted_at desc limit 1;
  if found then
    select slot into v_slot from team_members where id = s.member_id;
    v_out := v_out || jsonb_build_object('submission', jsonb_build_object(
      'id', s.id, 'status', s.status, 'answer', s.answer, 'explanation', s.explanation,
      'submitted_by_slot', v_slot, 'submitted_at', app.epoch_ms(s.submitted_at),
      'reviewed_at', app.epoch_ms(s.reviewed_at), 'review_note', s.review_note,
      'reward_awarded', s.reward_awarded));
  end if;

  if v_state = 'ACTIVE' then
    select * into s from submissions
     where team_id = p_team_id and question_id = p_question_id and status = 'REJECTED'
     order by reviewed_at desc limit 1;
    if found then
      v_out := v_out || jsonb_build_object('last_rejection', jsonb_build_object(
        'note', s.review_note, 'reviewed_at', app.epoch_ms(s.reviewed_at)));
    end if;
  end if;
  return v_out;
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- buy_hint(team_id, member_id, question_id, tier, idempotency_key)                         participant, TEAM-WIDE
-- A hint bought by one member belongs to the whole team (hint_purchases is keyed by team + hint). The price is read from
-- hints.cost under the team lock and charged once. Allowed while the question is ACTIVE, PENDING_APPROVAL or APPROVED
-- (a hint is a reading aid and costs no question time); refused on LOCKED / AVAILABLE (QUESTION_NOT_ACTIVE) and
-- TIMED_OUT (QUESTION_TIMED_OUT). Tier 2 needs Tier 1 of the same question (HINT_TIER1_REQUIRED, nothing charged).
-- Buying a hint the team already owns succeeds with already_owned = true: no charge, no ledger row, no version bump.
--   Rejections: FORBIDDEN · VALIDATION_FAILED (tier / key) · COMPETITION_NOT_RUNNING · COMPETITION_PAUSED ·
--               TEAM_NOT_STARTED · TEAM_ENDED · ALREADY_SUBMITTED · NOT_FOUND (question, or no hint at that tier) ·
--               THEME_LOCKED · QUESTION_NOT_ACTIVE · QUESTION_TIMED_OUT · HINT_TIER1_REQUIRED ·
--               INSUFFICIENT_COINS {have, need}
-- Result: { replayed, already_owned, tier, hint: { tier, body_md }, question: <app.question_json>, state: <snapshot> }
-- ---------------------------------------------------------------------------------------------------------------
create function public.buy_hint(p_team_id uuid, p_member_id uuid, p_question_id smallint, p_tier smallint, p_idem_key uuid) returns jsonb
language plpgsql security definer
set search_path = pg_catalog, public, extensions, app, pg_temp
as $$
declare
  v_team    teams%rowtype;
  v_tq      team_questions%rowtype;
  v_hint    hints%rowtype;
  v_fp      text := 'question:' || coalesce(p_question_id::text, '') || '|tier:' || coalesce(p_tier::text, '')
                    || '|member:' || coalesce(p_member_id::text, '');
  v_replay  jsonb;
  v_now     timestamptz;
  v_balance int;
  v_owned   boolean;
  v_resp    jsonb;
begin
  perform app.assert_member(p_team_id, p_member_id);
  if p_idem_key is null then
    perform app.fail('VALIDATION_FAILED', jsonb_build_object('fields', jsonb_build_array('idempotencyKey')));
  end if;
  if p_question_id is null or p_tier is null or p_tier not in (1, 2) then
    perform app.fail('VALIDATION_FAILED', jsonb_build_object('fields', jsonb_build_array('tier')));
  end if;

  v_team := app.lock_team(p_team_id);
  v_replay := app.idem_lookup(p_team_id, p_idem_key, 'buy_hint', v_fp);
  if v_replay is not null then
    return v_replay || '{"replayed": true}'::jsonb;
  end if;

  perform app.assert_playable(v_team);
  perform app.settle_questions(p_team_id);

  perform 1 from questions where id = p_question_id;
  if not found then
    perform app.fail('NOT_FOUND');
  end if;
  select * into v_tq from team_questions where team_id = p_team_id and question_id = p_question_id for update;
  if not found then
    perform app.fail('THEME_LOCKED');
  end if;
  if v_tq.state = 'TIMED_OUT' then
    perform app.fail('QUESTION_TIMED_OUT');
  elsif v_tq.state not in ('ACTIVE', 'PENDING_APPROVAL', 'APPROVED') then
    perform app.fail('QUESTION_NOT_ACTIVE');                           -- LOCKED, AVAILABLE
  end if;

  select * into v_hint from hints where question_id = p_question_id and tier = p_tier;
  if not found then
    perform app.fail('NOT_FOUND');                                     -- the content has no hint at that tier
  end if;

  v_owned := exists (select 1 from hint_purchases where team_id = p_team_id and hint_id = v_hint.id);
  if not v_owned then
    if p_tier = 2 and not exists (select 1 from hint_purchases p join hints h on h.id = p.hint_id
                                   where p.team_id = p_team_id and h.question_id = p_question_id and h.tier = 1) then
      perform app.fail('HINT_TIER1_REQUIRED');                         -- nothing charged
    end if;
    if v_team.coins < v_hint.cost then
      perform app.fail('INSUFFICIENT_COINS', jsonb_build_object('have', v_team.coins, 'need', v_hint.cost));
    end if;

    v_now := app.now();
    update teams set coins = coins - v_hint.cost, state_version = state_version + 1
     where id = p_team_id returning coins into v_balance;
    if v_hint.cost > 0 then
      insert into coin_transactions (team_id, type, amount, balance_after, hint_id, question_id, member_id, created_at)
      values (p_team_id, 'HINT_PURCHASE', -v_hint.cost, v_balance, v_hint.id, p_question_id, p_member_id, v_now);
    end if;
    insert into hint_purchases (team_id, hint_id, purchased_by, cost_paid, purchased_at)
    values (p_team_id, v_hint.id, p_member_id, v_hint.cost, v_now);

    insert into audit_events (occurred_at, actor_kind, member_id, team_id, event_type, entity_type, entity_id, payload, request_id)
    values (v_now, 'MEMBER', p_member_id, p_team_id, 'HINT_PURCHASED', 'HINT', v_hint.id::text,
            jsonb_build_object('question_id', p_question_id, 'tier', p_tier, 'hint_id', v_hint.id, 'cost', v_hint.cost,
                               'balance_before', v_team.coins, 'balance_after', v_balance),
            p_idem_key);
  end if;

  v_resp := jsonb_build_object('replayed', false, 'already_owned', v_owned, 'tier', p_tier,
                               'hint', jsonb_build_object('tier', p_tier, 'body_md', v_hint.body_md),
                               'question', app.question_json(p_team_id, p_question_id),
                               'state', app.team_state_json(p_team_id, p_member_id));
  perform app.idem_store(p_team_id, p_idem_key, 'buy_hint', v_fp, v_resp);
  return v_resp;
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- buy_time(team_id, member_id, question_id, option_id, expected_purchase_count, idempotency_key)    participant, TEAM-WIDE
-- Moves the deadline of THIS question for the whole team by the option's seconds and charges the option's cost. It never
-- writes teams.ends_at: the Ultimate Team Timer is not extended, and the question's playable time stays bounded by it
-- (app.question_clock), so seconds that would run past the team's end simply cannot be used.
-- expected_purchase_count is the number of purchases the caller saw; if another member bought in the meantime the answer
-- is STALE_PURCHASE_COUNT {count} and nothing is charged (two members cannot buy twice by accident). Only an ACTIVE
-- question can be extended (an overdue one was just settled to TIMED_OUT; PENDING_APPROVAL has a frozen timer).
--   Rejections: FORBIDDEN · VALIDATION_FAILED · COMPETITION_NOT_RUNNING · COMPETITION_PAUSED · TEAM_NOT_STARTED ·
--               TEAM_ENDED · ALREADY_SUBMITTED · NOT_FOUND (question / option of another question) · THEME_LOCKED ·
--               QUESTION_TIMED_OUT · QUESTION_NOT_ACTIVE · STALE_PURCHASE_COUNT {count} · TIME_PURCHASE_LIMIT ·
--               INSUFFICIENT_COINS {have, need}
-- Result: { replayed, purchase: { seq, option_id, seconds, cost }, question: <app.question_json>, state: <snapshot> }
-- ---------------------------------------------------------------------------------------------------------------
create function public.buy_time(p_team_id uuid, p_member_id uuid, p_question_id smallint, p_option_id smallint,
                                p_expected_count int, p_idem_key uuid) returns jsonb
language plpgsql security definer
set search_path = pg_catalog, public, extensions, app, pg_temp
as $$
declare
  v_team    teams%rowtype;
  v_tq      team_questions%rowtype;
  v_opt     question_buy_time_options%rowtype;
  v_fp      text := 'question:' || coalesce(p_question_id::text, '') || '|option:' || coalesce(p_option_id::text, '')
                    || '|expected:' || coalesce(p_expected_count::text, '') || '|member:' || coalesce(p_member_id::text, '');
  v_replay  jsonb;
  v_now     timestamptz;
  v_used    int;
  v_seq     int;
  v_balance int;
  v_old_dl  timestamptz;
  v_new_dl  timestamptz;
  v_resp    jsonb;
begin
  perform app.assert_member(p_team_id, p_member_id);
  if p_idem_key is null then
    perform app.fail('VALIDATION_FAILED', jsonb_build_object('fields', jsonb_build_array('idempotencyKey')));
  end if;
  if p_question_id is null or p_option_id is null or p_expected_count is null or p_expected_count < 0 then
    perform app.fail('VALIDATION_FAILED', jsonb_build_object('fields', jsonb_build_array('optionId', 'expectedPurchaseCount')));
  end if;

  v_team := app.lock_team(p_team_id);
  v_replay := app.idem_lookup(p_team_id, p_idem_key, 'buy_time', v_fp);
  if v_replay is not null then
    return v_replay || '{"replayed": true}'::jsonb;
  end if;

  perform app.assert_playable(v_team);
  perform app.settle_questions(p_team_id);

  perform 1 from questions where id = p_question_id;
  if not found then
    perform app.fail('NOT_FOUND');
  end if;
  select * into v_tq from team_questions where team_id = p_team_id and question_id = p_question_id for update;
  if not found then
    perform app.fail('THEME_LOCKED');
  end if;
  if v_tq.state = 'TIMED_OUT' then
    perform app.fail('QUESTION_TIMED_OUT');
  elsif v_tq.state <> 'ACTIVE' then
    perform app.fail('QUESTION_NOT_ACTIVE');                           -- LOCKED, AVAILABLE, PENDING_APPROVAL, APPROVED
  end if;
  if v_tq.time_purchase_count <> p_expected_count then
    perform app.fail('STALE_PURCHASE_COUNT', jsonb_build_object('count', v_tq.time_purchase_count));
  end if;

  select * into v_opt from question_buy_time_options where id = p_option_id and question_id = p_question_id;
  if not found then
    perform app.fail('NOT_FOUND');
  end if;
  select count(*) into v_used from team_time_purchases
   where team_id = p_team_id and question_id = p_question_id and option_id = p_option_id;
  if v_opt.max_purchases is not null and v_used >= v_opt.max_purchases then
    perform app.fail('TIME_PURCHASE_LIMIT');
  end if;
  if v_team.coins < v_opt.cost then
    perform app.fail('INSUFFICIENT_COINS', jsonb_build_object('have', v_team.coins, 'need', v_opt.cost));
  end if;

  v_now := app.now();
  v_seq := v_tq.time_purchase_count + 1;
  v_old_dl := v_tq.timer_deadline;
  v_new_dl := v_tq.timer_deadline + make_interval(secs => v_opt.seconds);

  update teams set coins = coins - v_opt.cost, state_version = state_version + 1
   where id = p_team_id returning coins into v_balance;                -- teams.ends_at is deliberately NOT touched
  if v_opt.cost > 0 then
    insert into coin_transactions (team_id, type, amount, balance_after, question_id, purchase_seq, member_id, created_at)
    values (p_team_id, 'TIME_PURCHASE', -v_opt.cost, v_balance, p_question_id, v_seq, p_member_id, v_now);
  end if;
  insert into team_time_purchases (team_id, question_id, seq, option_id, seconds_added, cost_paid, purchased_by, purchased_at)
  values (p_team_id, p_question_id, v_seq, p_option_id, v_opt.seconds, v_opt.cost, p_member_id, v_now);
  update team_questions
     set timer_deadline = v_new_dl, extra_seconds = extra_seconds + v_opt.seconds, time_purchase_count = v_seq
   where team_id = p_team_id and question_id = p_question_id;

  insert into audit_events (occurred_at, actor_kind, member_id, team_id, event_type, entity_type, entity_id, payload, request_id)
  values (v_now, 'MEMBER', p_member_id, p_team_id, 'TIME_PURCHASED', 'QUESTION', p_question_id::text,
          jsonb_build_object('question_id', p_question_id, 'option_id', p_option_id, 'seq', v_seq,
                             'seconds', v_opt.seconds, 'cost', v_opt.cost,
                             'old_deadline', app.epoch_ms(v_old_dl), 'new_deadline', app.epoch_ms(v_new_dl),
                             'balance_before', v_team.coins, 'balance_after', v_balance),
          p_idem_key);

  v_resp := jsonb_build_object('replayed', false,
                               'purchase', jsonb_build_object('seq', v_seq, 'option_id', p_option_id,
                                                              'seconds', v_opt.seconds, 'cost', v_opt.cost),
                               'question', app.question_json(p_team_id, p_question_id),
                               'state', app.team_state_json(p_team_id, p_member_id));
  perform app.idem_store(p_team_id, p_idem_key, 'buy_time', v_fp, v_resp);
  return v_resp;
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- final_submit(team_id, member_id, confirm, idempotency_key)                                participant, TEAM-WIDE
-- The team ends its own run: status FINAL_SUBMITTED, ended_at = now, final_submitted_at/by recorded, in one UPDATE under
-- the team lock. This is the same terminal freeze as the timer reaching zero: every clock reads ended_at from then on,
-- remaining time is constant, and every participant mutation is refused by app.assert_playable (ALREADY_SUBMITTED).
-- It persists across logout / login because it is only database state. Answers waiting for review stay reviewable
-- (approve pays once; the next question does not open). Scores (final_*) are NOT computed here (B16).
-- `confirm` must be true. The losing caller of a race gets ALREADY_SUBMITTED; a team whose timer ran out first gets
-- TEAM_ENDED (it is ENDED, not FINAL_SUBMITTED); while the competition is paused: COMPETITION_PAUSED.
-- Result: { replayed, state: <snapshot> }
-- ---------------------------------------------------------------------------------------------------------------
create function public.final_submit(p_team_id uuid, p_member_id uuid, p_confirm boolean, p_idem_key uuid) returns jsonb
language plpgsql security definer
set search_path = pg_catalog, public, extensions, app, pg_temp
as $$
declare
  v_team    teams%rowtype;
  v_fp      text := 'member:' || coalesce(p_member_id::text, '');
  v_replay  jsonb;
  v_now     timestamptz;
  v_pending int;
  v_active  int;
  v_resp    jsonb;
begin
  perform app.assert_member(p_team_id, p_member_id);
  if p_idem_key is null then
    perform app.fail('VALIDATION_FAILED', jsonb_build_object('fields', jsonb_build_array('idempotencyKey')));
  end if;
  if p_confirm is distinct from true then
    perform app.fail('VALIDATION_FAILED', jsonb_build_object('fields', jsonb_build_array('confirm')));
  end if;

  v_team := app.lock_team(p_team_id);
  v_replay := app.idem_lookup(p_team_id, p_idem_key, 'final_submit', v_fp);
  if v_replay is not null then
    return v_replay || '{"replayed": true}'::jsonb;
  end if;

  perform app.assert_playable(v_team);
  perform app.settle_questions(p_team_id);

  v_now := app.now();
  select count(*) filter (where state = 'PENDING_APPROVAL'), count(*) filter (where state = 'ACTIVE')
    into v_pending, v_active
    from team_questions where team_id = p_team_id;

  update teams
     set status = 'FINAL_SUBMITTED', ended_at = v_now, final_submitted_at = v_now, final_submitted_by = p_member_id,
         state_version = state_version + 1
   where id = p_team_id;

  insert into audit_events (occurred_at, actor_kind, member_id, team_id, event_type, entity_type, entity_id, payload, request_id)
  values (v_now, 'MEMBER', p_member_id, p_team_id, 'TEAM_FINAL_SUBMITTED', 'TEAM', p_team_id::text,
          jsonb_build_object('submitted_at', app.epoch_ms(v_now), 'pending_submissions', v_pending,
                             'active_questions', v_active, 'coins', v_team.coins,
                             'remaining_seconds', greatest(0, floor(extract(epoch from (v_team.ends_at - v_now))))::int),
          p_idem_key);

  v_resp := jsonb_build_object('replayed', false, 'state', app.team_state_json(p_team_id, p_member_id));
  perform app.idem_store(p_team_id, p_idem_key, 'final_submit', v_fp, v_resp);
  return v_resp;
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- disapprove_submission — re-declared with ONE change (see the header): a frozen team's returned question gets
-- `question clock + frozen remaining` instead of `now + frozen remaining`.
-- ---------------------------------------------------------------------------------------------------------------
create or replace function public.disapprove_submission(p_staff_id uuid, p_submission_id uuid, p_note text, p_idem_key uuid) returns jsonb
language plpgsql security definer
set search_path = pg_catalog, public, extensions, app, pg_temp
as $$
declare
  v_team_id uuid;
  v_team    teams%rowtype;
  v_sub     submissions%rowtype;
  v_tq      team_questions%rowtype;
  v_note    text := nullif(btrim(coalesce(p_note, '')), '');
  v_fp      text := 'submission:' || coalesce(p_submission_id::text, '') || '|note:' || md5(coalesce(v_note, ''));
  v_replay  jsonb;
  v_comp    competition%rowtype;
  v_now     timestamptz;
  v_resp    jsonb;
begin
  if p_staff_id is null or not exists (select 1 from staff_users where id = p_staff_id and is_active) then
    perform app.fail('FORBIDDEN');
  end if;
  if p_idem_key is null then
    perform app.fail('VALIDATION_FAILED', jsonb_build_object('fields', jsonb_build_array('idempotencyKey')));
  end if;
  if v_note is not null and length(v_note) > 500 then
    perform app.fail('VALIDATION_FAILED', jsonb_build_object('fields', jsonb_build_array('note')));
  end if;
  select team_id into v_team_id from submissions where id = p_submission_id;
  if not found then
    perform app.fail('NOT_FOUND');
  end if;
  perform app.require_reviewer(p_staff_id, v_team_id);

  v_team := app.lock_team(v_team_id);
  v_replay := app.idem_lookup(p_staff_id, p_idem_key, 'disapprove_submission', v_fp);
  if v_replay is not null then
    return v_replay || '{"replayed": true}'::jsonb;
  end if;

  select * into v_comp from competition where id = 1;
  if v_comp.status = 'PAUSED' then
    perform app.fail('COMPETITION_PAUSED');
  elsif v_comp.status <> 'RUNNING' then
    perform app.fail('COMPETITION_NOT_RUNNING');
  end if;

  select * into v_sub from submissions where id = p_submission_id for update;
  if v_sub.status <> 'PENDING' then
    perform app.fail('SUBMISSION_NOT_PENDING');
  end if;
  v_now := app.now();
  if v_team.status = 'RUNNING' and v_now < v_team.ends_at then
    perform app.settle_questions(v_team_id);
  end if;

  select * into v_tq from team_questions where team_id = v_team_id and question_id = v_sub.question_id for update;
  if not found or v_tq.state <> 'PENDING_APPROVAL' then
    perform app.fail('SUBMISSION_NOT_PENDING');
  end if;

  update submissions
     set status = 'REJECTED', reviewed_by = p_staff_id, reviewed_at = v_now, review_note = v_note
   where id = p_submission_id;
  update team_questions
     set state = 'ACTIVE', timer_deadline = app.question_clock(v_team) + make_interval(secs => v_tq.timer_remaining_seconds),
         timer_remaining_seconds = null
   where team_id = v_team_id and question_id = v_sub.question_id;

  update teams set state_version = state_version + 1 where id = v_team_id;
  insert into audit_events (occurred_at, actor_kind, staff_id, team_id, event_type, entity_type, entity_id, payload, request_id)
  values (v_now, 'STAFF', p_staff_id, v_team_id, 'SUBMISSION_REJECTED', 'SUBMISSION', p_submission_id::text,
          jsonb_build_object('question_id', v_sub.question_id, 'has_note', v_note is not null,
                             'resumed_remaining_seconds', v_tq.timer_remaining_seconds),
          p_idem_key);

  v_resp := jsonb_build_object('replayed', false,
                               'submission', jsonb_build_object('id', p_submission_id, 'status', 'REJECTED'));
  perform app.idem_store(p_staff_id, p_idem_key, 'disapprove_submission', v_fp, v_resp);
  return v_resp;
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- Privileges
-- ---------------------------------------------------------------------------------------------------------------
-- (the two re-declared functions are listed too: CREATE OR REPLACE keeps their old privileges, this just states them)
revoke all on function app.question_json(uuid, smallint)                            from public, anon, authenticated;
revoke all on function public.buy_hint(uuid, uuid, smallint, smallint, uuid)        from public, anon, authenticated;
revoke all on function public.buy_time(uuid, uuid, smallint, smallint, int, uuid)   from public, anon, authenticated;
revoke all on function public.final_submit(uuid, uuid, boolean, uuid)               from public, anon, authenticated;
revoke all on function public.disapprove_submission(uuid, uuid, text, uuid)         from public, anon, authenticated;
grant execute on function app.question_json(uuid, smallint)                            to service_role;
grant execute on function public.buy_hint(uuid, uuid, smallint, smallint, uuid)        to service_role;
grant execute on function public.buy_time(uuid, uuid, smallint, smallint, int, uuid)   to service_role;
grant execute on function public.final_submit(uuid, uuid, boolean, uuid)               to service_role;
grant execute on function public.disapprove_submission(uuid, uuid, text, uuid)         to service_role;

-- ===== 20261006000018_scoring_leaderboard_penalty.sql =====
-- Patch B / migration 18 — Phase B16: scoring, live leaderboard and the UFM penalty.
--
-- WHAT THIS DOES
--   1. Score (STATE_MACHINE / SCORING_AND_LEADERBOARD): a DERIVED value, never a stored live column and never written per
--      minute:
--          score = completed_themes × 500 + solved_questions × 100 + remaining_coins − minutes_taken × 5
--          minutes_taken = round((timer_seconds − remaining_seconds) / 60)       (elapsed time of THIS team's allowance;
--                          for a 4 h team it is exactly round(240 − remaining minutes); a 2 h legacy team is not charged
--                          for the hours it never had). It may be negative.
--      While a team is playing (or has not started) every read derives the score from the live tables (app.team_scores).
--   2. Freeze: when a team becomes terminal — Final Submit (public.final_submit) OR the timer / competition end
--      (app.expire_team, which finalize_team_if_due, expire_due_teams and set_competition_status all use) — the score is
--      written ONCE into the existing teams.final_* columns (app.freeze_final_score). From then on the frozen values
--      are authoritative: a late approval still pays coins (B14) but can never change the score. Both paths use the same
--      function, so manual and automatic finalization share one basis, and nothing drifts afterwards.
--   3. Leaderboard: app.leaderboard_rows is one SQL statement over one MVCC snapshot (so rank, score and "me" are always
--      coherent). Order: started teams before NOT_STARTED ones, then score desc, minutes_taken asc, Team ID asc (C
--      collation, code-point). Served by get_leaderboard (staff) and get_team_leaderboard (participants).
--   4. UFM penalty: penalize_team (owner ADMIN only). The official score becomes 0 and the team is frozen (a RUNNING team
--      is ended through app.expire_team; a team that is already terminal is only marked). Gameplay history (answers,
--      submissions, ledger, final_* gameplay snapshot) is NOT touched: the penalty is an override. Atomic, idempotent,
--      audited (UFM_PENALIZED). This replaces the never-built "UFM Reset" design (score_reset_* columns stay, unused);
--      Disqualify (score_override = -1201) stays unbuilt and wins over everything if it is ever used.
--   5. Re-declared with ONE additive change each (nothing else changed): app.expire_team and public.final_submit (freeze),
--      public.approve_submission (an approval that finds an expired, not yet persisted team ends it at its end first, so
--      the freeze happens before the late reward) and public.admin_matrix (+ `ufm_penalized`, for the My Teams grid).
--   6. Existing FINAL_SUBMITTED / ENDED teams get their score frozen from the current data (backfill).

-- ---------------------------------------------------------------------------------------------------------------
-- 1. Penalty columns
-- ---------------------------------------------------------------------------------------------------------------
alter table teams
  add column ufm_penalized_at timestamptz,
  add column ufm_penalized_by uuid references staff_users(id) on delete restrict;

alter table teams add constraint teams_ufm_penalty_paired
  check ((ufm_penalized_at is null) = (ufm_penalized_by is null));
-- a penalty only exists on a team that has started and can no longer play
alter table teams add constraint teams_ufm_penalty_terminal
  check (ufm_penalized_at is null or status in ('FINAL_SUBMITTED', 'ENDED', 'DISQUALIFIED'));
-- the four cached gameplay values are written together
alter table teams add constraint teams_final_cache_paired
  check ((final_score is null) = (final_completed_themes is null)
     and (final_score is null) = (final_solved_questions is null)
     and (final_score is null) = (final_minutes_taken is null));

comment on column teams.ufm_penalized_at is 'B16: set once by penalize_team; the official score is then 0. Never cleared.';
comment on column teams.final_score is
  'B16: the GAMEPLAY score frozen at the terminal moment (app.freeze_final_score). The official score also honours ufm_penalized_at / score_override.';

create function app.teams_ufm_penalty_immutable() returns trigger
language plpgsql
set search_path = pg_catalog, public, app, pg_temp
as $$
begin
  if old.ufm_penalized_at is not null
     and (new.ufm_penalized_at is distinct from old.ufm_penalized_at or new.ufm_penalized_by is distinct from old.ufm_penalized_by) then
    raise exception 'UFM_PENALTY_IMMUTABLE' using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger teams_ufm_penalty_immutable before update of ufm_penalized_at, ufm_penalized_by on teams
  for each row execute function app.teams_ufm_penalty_immutable();

-- ---------------------------------------------------------------------------------------------------------------
-- 2. The formula, in exactly one place
-- ---------------------------------------------------------------------------------------------------------------
-- No SET clause on purpose: it touches no object, and a function without one is inlined into the calling query (one call per
-- team per board read would otherwise cost a full function setup each).
create function app.compute_score(p_completed int, p_solved int, p_coins int, p_minutes int) returns int
language sql immutable
as $$ select p_completed * 500 + p_solved * 100 + p_coins - p_minutes * 5 $$;

-- ---------------------------------------------------------------------------------------------------------------
-- app.team_scores_all(now) — one row per team, read-only, ONE statement (one snapshot).  (app.team_scores below filters it.)
--   completed / solved   live: APPROVED questions (a theme is completed at 5 of 5); frozen: teams.final_*
--   minutes              live: round((timer_seconds − remaining)/60) with remaining = ends_at − clock, clamped to
--                        [0, timer_seconds]; clock = least(now, ended_at, paused_at while PAUSED), exactly the team clock of
--                        every other read. Frozen: teams.final_minutes_taken. A team that has not started: 0.
--   gameplay_score       the formula above (frozen value once the team is terminal)
--   official_score       0 for a penalised team, score_override for a disqualified one, else gameplay_score
-- A terminal team whose final_* are still NULL (cannot happen after the backfill below) is derived with clock = ended_at.
-- ---------------------------------------------------------------------------------------------------------------
create function app.team_scores_all(p_now timestamptz)
returns table (team_id uuid, team_code text, status team_status, completed int, solved int, coins int, minutes int,
               gameplay_score int, official_score int, penalized boolean)
language sql stable
set search_path = pg_catalog, public, app, pg_temp
as $$
  with paused as (
    select case when c.status = 'PAUSED' then c.paused_at end as at from competition c where c.id = 1
  ), per_theme as (
    select tq.team_id, tq.theme_id, count(*) as n
      from team_questions tq
     where tq.state = 'APPROVED'
     group by tq.team_id, tq.theme_id
  ), prog as (
    select pt.team_id, sum(pt.n)::int as solved, (count(*) filter (where pt.n = 5))::int as completed
      from per_theme pt
     group by pt.team_id
  ), basis as (
    select t.id, t.team_code, t.status, t.coins, t.ufm_penalized_at, t.score_override,
           (t.final_score is not null) as frozen,
           t.final_score, t.final_completed_themes, t.final_solved_questions, t.final_minutes_taken,
           coalesce(pr.completed, 0) as live_completed, coalesce(pr.solved, 0) as live_solved,
           case when t.started_at is null then 0
                else round((t.timer_seconds
                            - greatest(0, least(t.timer_seconds,
                                                extract(epoch from (t.ends_at - least(p_now, coalesce(t.ended_at, 'infinity'::timestamptz),
                                                                                       (select at from paused)))))))
                           / 60.0)::int
           end as live_minutes
      from teams t
      left join prog pr on pr.team_id = t.id
  )
  select b.id, b.team_code, b.status,
         case when b.frozen then b.final_completed_themes else b.live_completed end,
         case when b.frozen then b.final_solved_questions  else b.live_solved end,
         b.coins,
         case when b.frozen then b.final_minutes_taken else b.live_minutes end,
         g.score,
         case when b.ufm_penalized_at is not null then 0 else coalesce(b.score_override, g.score) end,
         (b.ufm_penalized_at is not null)
    from basis b
    cross join lateral (
      select case when b.frozen then b.final_score
                  else app.compute_score(b.live_completed, b.live_solved, b.coins, b.live_minutes) end as score) g
$$;

-- app.team_scores(now, team?) — the same rows for one team (or all). Deliberately a thin filter over team_scores_all: an
-- "optional parameter" predicate (`p_team_id is null or ... = p_team_id`) inside the aggregation makes the planner choose a
-- nested-loop plan that costs ~10x more for the whole board (measured with 100 teams), and the board is the hot path.
create function app.team_scores(p_now timestamptz, p_team_id uuid default null)
returns table (team_id uuid, team_code text, status team_status, completed int, solved int, coins int, minutes int,
               gameplay_score int, official_score int, penalized boolean)
language sql stable
set search_path = pg_catalog, public, app, pg_temp
as $$
  select * from app.team_scores_all(p_now) s where p_team_id is null or s.team_id = p_team_id
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- app.freeze_final_score(team) — writes the gameplay score of a TERMINAL team into teams.final_* exactly once.
-- Idempotent (a team that already has final_score is left alone) and a no-op for a team that is not terminal. The caller
-- has already written status / ended_at in the same transaction and holds the team lock.
-- ---------------------------------------------------------------------------------------------------------------
create function app.freeze_final_score(p_team_id uuid) returns void
language sql
set search_path = pg_catalog, public, app, pg_temp
as $$
  update teams t
     set final_score = s.gameplay_score, final_completed_themes = s.completed,
         final_solved_questions = s.solved, final_minutes_taken = s.minutes
    from app.team_scores(app.now(), p_team_id) s
   where t.id = p_team_id and s.team_id = t.id
     and t.final_score is null
     and t.status in ('FINAL_SUBMITTED', 'ENDED', 'DISQUALIFIED')
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- 3. Re-declared with ONE additive line each (see the header): the terminal moment now freezes the score.
-- ---------------------------------------------------------------------------------------------------------------

create or replace function app.expire_team(p_team_id uuid, p_reason text, p_ended_at timestamptz, p_staff_id uuid default null)
returns void
language plpgsql
set search_path = pg_catalog, public, app, pg_temp
as $$
declare
  t     teams%rowtype;
  v_end timestamptz;
begin
  select * into t from teams where id = p_team_id;
  if not found or t.status <> 'RUNNING' then
    return;
  end if;
  v_end := least(t.ends_at, p_ended_at);

  update team_questions
     set state = 'TIMED_OUT', timed_out_at = timer_deadline, timer_deadline = null
   where team_id = p_team_id and state = 'ACTIVE' and timer_deadline <= v_end;

  update teams set status = 'ENDED', ended_at = v_end where id = p_team_id;
  perform app.freeze_final_score(p_team_id);                            -- B16: the score is fixed at this instant

  insert into audit_events (occurred_at, actor_kind, staff_id, team_id, event_type, entity_type, entity_id, payload)
  values (app.now(), case when p_staff_id is null then 'SYSTEM' else 'STAFF' end, p_staff_id, p_team_id,
          'TEAM_ENDED', 'TEAM', p_team_id::text,
          jsonb_build_object('reason', p_reason, 'ended_at', app.epoch_ms(v_end), 'ends_at', app.epoch_ms(t.ends_at)));
end $$;


create or replace function public.final_submit(p_team_id uuid, p_member_id uuid, p_confirm boolean, p_idem_key uuid) returns jsonb
language plpgsql security definer
set search_path = pg_catalog, public, extensions, app, pg_temp
as $$
declare
  v_team    teams%rowtype;
  v_fp      text := 'member:' || coalesce(p_member_id::text, '');
  v_replay  jsonb;
  v_now     timestamptz;
  v_pending int;
  v_active  int;
  v_resp    jsonb;
begin
  perform app.assert_member(p_team_id, p_member_id);
  if p_idem_key is null then
    perform app.fail('VALIDATION_FAILED', jsonb_build_object('fields', jsonb_build_array('idempotencyKey')));
  end if;
  if p_confirm is distinct from true then
    perform app.fail('VALIDATION_FAILED', jsonb_build_object('fields', jsonb_build_array('confirm')));
  end if;

  v_team := app.lock_team(p_team_id);
  v_replay := app.idem_lookup(p_team_id, p_idem_key, 'final_submit', v_fp);
  if v_replay is not null then
    return v_replay || '{"replayed": true}'::jsonb;
  end if;

  perform app.assert_playable(v_team);
  perform app.settle_questions(p_team_id);

  v_now := app.now();
  select count(*) filter (where state = 'PENDING_APPROVAL'), count(*) filter (where state = 'ACTIVE')
    into v_pending, v_active
    from team_questions where team_id = p_team_id;

  update teams
     set status = 'FINAL_SUBMITTED', ended_at = v_now, final_submitted_at = v_now, final_submitted_by = p_member_id,
         state_version = state_version + 1
   where id = p_team_id;

  perform app.freeze_final_score(p_team_id);                            -- B16: same terminal basis as the timer expiry

  insert into audit_events (occurred_at, actor_kind, member_id, team_id, event_type, entity_type, entity_id, payload, request_id)
  values (v_now, 'MEMBER', p_member_id, p_team_id, 'TEAM_FINAL_SUBMITTED', 'TEAM', p_team_id::text,
          jsonb_build_object('submitted_at', app.epoch_ms(v_now), 'pending_submissions', v_pending,
                             'active_questions', v_active, 'coins', v_team.coins,
                             'remaining_seconds', greatest(0, floor(extract(epoch from (v_team.ends_at - v_now))))::int),
          p_idem_key);

  v_resp := jsonb_build_object('replayed', false, 'state', app.team_state_json(p_team_id, p_member_id));
  perform app.idem_store(p_team_id, p_idem_key, 'final_submit', v_fp, v_resp);
  return v_resp;
end $$;


create or replace function public.admin_matrix(p_staff_id uuid) returns jsonb
language plpgsql stable security definer
set search_path = pg_catalog, public, extensions, app, pg_temp
as $$
begin
  if p_staff_id is null or not exists (select 1 from staff_users where id = p_staff_id and role = 'ADMIN' and is_active) then
    perform app.fail('FORBIDDEN');
  end if;
  return jsonb_build_object(
    'server_now', app.epoch_ms(app.now()),
    'presence_timeout_seconds', app.presence_timeout_seconds(),
    'teams', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', t.id,
               'team_code', t.team_code,
               'name', t.name,
               'status', t.status::text,
               'final_submitted', (t.status = 'FINAL_SUBMITTED'),
               'ufm_penalized', (t.ufm_penalized_at is not null),
               'members', (select coalesce(jsonb_agg(jsonb_build_object('slot', p.slot, 'presence', p.presence::text)
                                                      order by p.slot), '[]'::jsonb)
                             from member_presence p where p.team_id = t.id),
               'themes', (select jsonb_agg(jsonb_build_object(
                                    'code', th.code,
                                    'state', case when c.pending > 0 then 'RED'
                                                  when c.approved = 5 then 'GREEN'
                                                  else 'NORMAL' end,
                                    'approved', c.approved,
                                    'pending', c.pending) order by th.id)
                            from themes th
                            cross join lateral (
                              select count(*) filter (where tq.state = 'APPROVED')         as approved,
                                     count(*) filter (where tq.state = 'PENDING_APPROVAL') as pending
                                from team_questions tq
                               where tq.team_id = t.id and tq.theme_id = th.id) c)
             ) order by t.created_at, t.team_code)
        from teams t where t.admin_id = p_staff_id), '[]'::jsonb));
end $$;


-- approve_submission — re-declared with ONE additive block (see the comment inside): an approval that discovers an expired,
-- not yet persisted team ends it at its end first, so a late reward cannot move a score the timer already fixed.
create or replace function public.approve_submission(p_staff_id uuid, p_submission_id uuid, p_idem_key uuid) returns jsonb
language plpgsql security definer
set search_path = pg_catalog, public, extensions, app, pg_temp
as $$
declare
  v_team_id  uuid;
  v_team     teams%rowtype;
  v_sub      submissions%rowtype;
  v_tq       team_questions%rowtype;
  v_q        questions%rowtype;
  v_fp       text := 'submission:' || coalesce(p_submission_id::text, '');
  v_replay   jsonb;
  v_comp     competition%rowtype;
  v_now      timestamptz;
  v_live     boolean;
  v_balance  int;
  v_next     smallint;
  v_resp     jsonb;
begin
  if p_staff_id is null or not exists (select 1 from staff_users where id = p_staff_id and is_active) then
    perform app.fail('FORBIDDEN');
  end if;
  if p_idem_key is null then
    perform app.fail('VALIDATION_FAILED', jsonb_build_object('fields', jsonb_build_array('idempotencyKey')));
  end if;
  select team_id into v_team_id from submissions where id = p_submission_id;
  if not found then
    perform app.fail('NOT_FOUND');
  end if;
  perform app.require_reviewer(p_staff_id, v_team_id);

  v_team := app.lock_team(v_team_id);                                  -- team first, then re-read the submission
  v_replay := app.idem_lookup(p_staff_id, p_idem_key, 'approve_submission', v_fp);
  if v_replay is not null then
    return v_replay || '{"replayed": true}'::jsonb;
  end if;

  select * into v_comp from competition where id = 1;
  if v_comp.status = 'PAUSED' then
    perform app.fail('COMPETITION_PAUSED');
  elsif v_comp.status <> 'RUNNING' then
    perform app.fail('COMPETITION_NOT_RUNNING');
  end if;

  select * into v_sub from submissions where id = p_submission_id for update;
  if v_sub.status <> 'PENDING' then
    perform app.fail('SUBMISSION_NOT_PENDING');
  end if;
  v_now := app.now();
  v_live := v_team.status = 'RUNNING' and v_now < v_team.ends_at;
  if v_team.status = 'RUNNING' and v_now >= v_team.ends_at then
    -- B16: the timer already ran out but nobody has persisted it yet. End the team AT its end (this also freezes its score)
    -- BEFORE this late reward is booked, so the reward pays coins (B14 / DEC-03) but can never move the score.
    perform app.expire_team(v_team_id, 'TIMER', v_team.ends_at);
  end if;
  if v_live then
    perform app.settle_questions(v_team_id);
  end if;

  select * into v_tq from team_questions where team_id = v_team_id and question_id = v_sub.question_id for update;
  if not found or v_tq.state <> 'PENDING_APPROVAL' then
    perform app.fail('SUBMISSION_NOT_PENDING');                        -- invariant: a PENDING submission <=> PENDING_APPROVAL
  end if;
  select * into v_q from questions where id = v_sub.question_id;

  update submissions
     set status = 'APPROVED', reviewed_by = p_staff_id, reviewed_at = v_now, reward_awarded = v_q.reward_coins
   where id = p_submission_id;
  update team_questions
     set state = 'APPROVED', approved_at = v_now, timer_remaining_seconds = null
   where team_id = v_team_id and question_id = v_sub.question_id;

  update teams set coins = coins + v_q.reward_coins, state_version = state_version + 1
   where id = v_team_id returning coins into v_balance;
  if v_q.reward_coins > 0 then
    insert into coin_transactions (team_id, type, amount, balance_after, question_id, submission_id, member_id, staff_id, created_at)
    values (v_team_id, 'QUESTION_REWARD', v_q.reward_coins, v_balance, v_sub.question_id, p_submission_id, v_sub.member_id, p_staff_id, v_now);
  end if;

  if v_q.ordinal < 5 and v_live then
    update team_questions tq
       set state = 'ACTIVE', activated_at = v_now,
           timer_deadline = v_now + make_interval(secs => nq.time_limit_seconds)
      from questions nq
     where tq.team_id = v_team_id and tq.theme_id = v_q.theme_id and tq.ordinal = v_q.ordinal + 1
       and tq.state = 'LOCKED' and nq.id = tq.question_id
    returning tq.question_id into v_next;
  end if;

  insert into audit_events (occurred_at, actor_kind, staff_id, team_id, event_type, entity_type, entity_id, payload, request_id)
  values (v_now, 'STAFF', p_staff_id, v_team_id, 'SUBMISSION_APPROVED', 'SUBMISSION', p_submission_id::text,
          jsonb_build_object('question_id', v_sub.question_id, 'reward', v_q.reward_coins,
                             'balance_after', v_balance, 'next_question_id', v_next),
          p_idem_key);

  v_resp := jsonb_build_object('replayed', false,
                               'submission', jsonb_build_object('id', p_submission_id, 'status', 'APPROVED'),
                               'reward_awarded', v_q.reward_coins,
                               'next_question_activated', v_next is not null);
  perform app.idem_store(p_staff_id, p_idem_key, 'approve_submission', v_fp, v_resp);
  return v_resp;
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- 4. Leaderboard
-- ---------------------------------------------------------------------------------------------------------------
create function app.leaderboard_rows(p_now timestamptz)
returns table (rank_no int, team_id uuid, team_code text, score int, minutes int)
language sql stable
set search_path = pg_catalog, public, app, pg_temp
as $$
  select (row_number() over (order by (s.status = 'NOT_STARTED'),        -- started teams first, unstarted last
                                      s.official_score desc,
                                      s.minutes asc,
                                      s.team_code collate "C" asc))::int,
         s.team_id, s.team_code, s.official_score, s.minutes
    from app.team_scores_all(p_now) s
$$;

-- get_leaderboard(staff_id) — ADMIN and SUPER_ADMIN (every team, as before). Shape gains `server_now`; rows unchanged.
create or replace function public.get_leaderboard(p_staff_id uuid) returns jsonb
language plpgsql stable security definer
set search_path = pg_catalog, public, extensions, app, pg_temp
as $$
begin
  if not exists (select 1 from staff_users where id = p_staff_id and role in ('ADMIN', 'SUPER_ADMIN') and is_active) then
    perform app.fail('FORBIDDEN');
  end if;
  -- a single statement: rank, score and server_now all come from one snapshot
  return (select jsonb_build_object(
                   'server_now', app.epoch_ms(n.v),
                   'rows', coalesce((select jsonb_agg(jsonb_build_object('rank', r.rank_no, 'team_id', r.team_code, 'score', r.score)
                                                      order by r.rank_no)
                                       from app.leaderboard_rows(n.v) r where r.rank_no <= 500), '[]'::jsonb))
            from (select app.now() as v) n);
end $$;

-- get_team_leaderboard(team_id, member_id) — a participant sees every team's rank / Team ID / score plus their own row.
-- `me` is taken from the same ranked set as `rows`, so the two can never disagree.
create function public.get_team_leaderboard(p_team_id uuid, p_member_id uuid) returns jsonb
language plpgsql stable security definer
set search_path = pg_catalog, public, extensions, app, pg_temp
as $$
begin
  perform app.assert_member(p_team_id, p_member_id);
  -- the ranking is computed ONCE (materialized) and both `rows` and `me` are read from that one result
  return (with n as (select app.now() as v),
               ranked as materialized (select r.* from app.leaderboard_rows((select v from n)) r)
          select jsonb_build_object(
                   'server_now', app.epoch_ms(n.v),
                   'rows', coalesce((select jsonb_agg(jsonb_build_object('rank', r.rank_no, 'team_id', r.team_code, 'score', r.score)
                                                      order by r.rank_no)
                                       from ranked r where r.rank_no <= 500), '[]'::jsonb),
                   'me', (select jsonb_build_object('rank', r.rank_no, 'team_id', r.team_code, 'score', r.score)
                            from ranked r where r.team_id = p_team_id))
            from n);
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- 5. penalize_team(staff_id, team_id, idempotency_key)               owner ADMIN only
--   * FORBIDDEN for anyone who is not an active ADMIN (participants never reach this function; a SUPER_ADMIN is refused);
--     NOT_FOUND for a team another admin owns (does not reveal that it exists).
--   * TEAM_NOT_STARTED: there is nothing to penalise before the team has started.
--   * RUNNING team  → app.expire_team(reason UFM_PENALTY, ended at the team clock, i.e. the pause instant while paused),
--                     which freezes the gameplay score; then the penalty is recorded. Already ENDED / FINAL_SUBMITTED →
--                     only recorded. Answers, submissions, ledger and the gameplay snapshot are never touched.
--   * Penalising an already penalised team (any key) is a no-op: changed:false, no second audit row, no version bump.
--   * One transaction under the team lock (competition share → team update), the global lock order.
--   Result: { replayed, changed, team: { id, team_code, status, official_score: 0, penalized_at } }
-- ---------------------------------------------------------------------------------------------------------------
create function public.penalize_team(p_staff_id uuid, p_team_id uuid, p_idem_key uuid) returns jsonb
language plpgsql security definer
set search_path = pg_catalog, public, extensions, app, pg_temp
as $$
declare
  v_team    teams%rowtype;
  v_fp      text := 'team:' || coalesce(p_team_id::text, '');
  v_replay  jsonb;
  v_now     timestamptz;
  v_changed boolean := false;
  v_prev    team_status;
  v_gameplay int;
  v_resp    jsonb;
begin
  perform app.require_owner_admin(p_staff_id, p_team_id);
  if p_idem_key is null then
    perform app.fail('VALIDATION_FAILED', jsonb_build_object('fields', jsonb_build_array('idempotencyKey')));
  end if;

  v_team := app.lock_team(p_team_id);
  v_replay := app.idem_lookup(p_staff_id, p_idem_key, 'penalize_team', v_fp);
  if v_replay is not null then
    return v_replay || '{"replayed": true}'::jsonb;
  end if;

  if v_team.ufm_penalized_at is null then
    if v_team.status = 'NOT_STARTED' then
      perform app.fail('TEAM_NOT_STARTED');
    end if;
    v_now := app.now();
    v_prev := v_team.status;
    if v_team.status = 'RUNNING' then
      perform app.expire_team(p_team_id, 'UFM_PENALTY', app.team_clock(v_team), p_staff_id);
    end if;
    update teams
       set ufm_penalized_at = v_now, ufm_penalized_by = p_staff_id, state_version = state_version + 1
     where id = p_team_id;
    select s.gameplay_score into v_gameplay from app.team_scores(v_now, p_team_id) s;

    insert into audit_events (occurred_at, actor_kind, staff_id, team_id, event_type, entity_type, entity_id, payload, request_id)
    values (v_now, 'STAFF', p_staff_id, p_team_id, 'UFM_PENALIZED', 'TEAM', p_team_id::text,
            jsonb_build_object('previous_status', v_prev::text, 'official_score', 0, 'gameplay_score', v_gameplay,
                               'penalized_at', app.epoch_ms(v_now)),
            p_idem_key);
    v_changed := true;
  end if;

  select jsonb_build_object('replayed', false, 'changed', v_changed,
                            'team', jsonb_build_object('id', t.id, 'team_code', t.team_code, 'status', t.status::text,
                                                       'official_score', 0, 'penalized_at', app.epoch_ms(t.ufm_penalized_at)))
    into v_resp from teams t where t.id = p_team_id;
  perform app.idem_store(p_staff_id, p_idem_key, 'penalize_team', v_fp, v_resp);
  return v_resp;
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- 6. Privileges: no PUBLIC, no anon, no authenticated; service_role only.
-- ---------------------------------------------------------------------------------------------------------------
revoke all on function app.teams_ufm_penalty_immutable()                       from public, anon, authenticated;
revoke all on function app.compute_score(int, int, int, int)                   from public, anon, authenticated;
revoke all on function app.team_scores_all(timestamptz)                        from public, anon, authenticated;
revoke all on function app.team_scores(timestamptz, uuid)                      from public, anon, authenticated;
revoke all on function app.freeze_final_score(uuid)                            from public, anon, authenticated;
revoke all on function app.leaderboard_rows(timestamptz)                       from public, anon, authenticated;
revoke all on function app.expire_team(uuid, text, timestamptz, uuid)          from public, anon, authenticated;
revoke all on function public.final_submit(uuid, uuid, boolean, uuid)          from public, anon, authenticated;
revoke all on function public.approve_submission(uuid, uuid, uuid)             from public, anon, authenticated;
revoke all on function public.admin_matrix(uuid)                               from public, anon, authenticated;
revoke all on function public.get_leaderboard(uuid)                            from public, anon, authenticated;
revoke all on function public.get_team_leaderboard(uuid, uuid)                 from public, anon, authenticated;
revoke all on function public.penalize_team(uuid, uuid, uuid)                  from public, anon, authenticated;

grant execute on function app.teams_ufm_penalty_immutable()                    to service_role;
grant execute on function app.compute_score(int, int, int, int)                to service_role;
grant execute on function app.team_scores_all(timestamptz)                     to service_role;
grant execute on function app.team_scores(timestamptz, uuid)                   to service_role;
grant execute on function app.freeze_final_score(uuid)                         to service_role;
grant execute on function app.leaderboard_rows(timestamptz)                    to service_role;
grant execute on function app.expire_team(uuid, text, timestamptz, uuid)       to service_role;
grant execute on function public.final_submit(uuid, uuid, boolean, uuid)       to service_role;
grant execute on function public.approve_submission(uuid, uuid, uuid)          to service_role;
grant execute on function public.admin_matrix(uuid)                            to service_role;
grant execute on function public.get_leaderboard(uuid)                         to service_role;
grant execute on function public.get_team_leaderboard(uuid, uuid)              to service_role;
grant execute on function public.penalize_team(uuid, uuid, uuid)               to service_role;

-- ---------------------------------------------------------------------------------------------------------------
-- 7. Backfill: teams that were already terminal before B16 get their score frozen from the data as it stands now (the
-- minutes are exact: the clock is the team's own ended_at). One SYSTEM audit row records how many.
-- ---------------------------------------------------------------------------------------------------------------
do $$
declare
  v_n int;
begin
  select count(*) into v_n from teams
   where status in ('FINAL_SUBMITTED', 'ENDED', 'DISQUALIFIED') and final_score is null;
  perform app.freeze_final_score(id) from teams
   where status in ('FINAL_SUBMITTED', 'ENDED', 'DISQUALIFIED') and final_score is null;
  if v_n > 0 and exists (select 1 from competition where id = 1) then
    insert into audit_events (occurred_at, actor_kind, event_type, entity_type, entity_id, payload)
    values (app.now(), 'SYSTEM', 'SCORES_BACKFILLED', 'COMPETITION', '1', jsonb_build_object('teams', v_n));
  end if;
end $$;

-- ===== 20261006000019_official_content.sql =====
-- B17 / migration 19 — official Concetto 26 content: 10 themes, 50 questions, 100 hints and the per-question rewards.
--
-- GENERATED by scripts/content/generate.mjs from content/concetto26/official-content.json (content JSON sha256 1c2133dd052a901aa6c9eae4fc2b418fa33b55b55ad9ffa7b4a423b16d17dcdb).
-- Do not edit by hand: change the JSON and regenerate (`node scripts/content/generate.mjs`; `--check` verifies it).
--
-- Order of events this migration has to be right for (Supabase runs migrations FIRST and supabase/seed.sql AFTER them on
-- `supabase db reset` / `supabase start`; `supabase db push` runs no seed unless --include-seed, which is also after):
--
--   A. UPGRADE of an existing database (production at B16): the 10 / 50 / 100 content rows already exist. Only their CONTENT
--      columns are overwritten:  themes.name, themes.description · questions.body_md, questions.reward_coins · hints.body_md.
--   B. FRESH database: the content tables are still EMPTY when this migration runs (the seed has not run yet). The official rows are
--      INSTALLED here, with the same structure the seed gives its rows (see "structure" below). When supabase/seed.sql runs after
--      it, every one of its content inserts is ON CONFLICT DO NOTHING, so the official text is kept; the seed still adds what is
--      not content (buy-time options, reviewer-key placeholders).
--   C. Any other shape (not exactly 0/0/0 or 10/50/100 rows) aborts the migration with nothing changed.
--
-- Structure of an installed row = what supabase/seed.sql gives it: difficulty EASY for themes 1-3, MEDIUM 4-7, HARD 8-10 (a question
-- has its theme's), unlock cost 100, display order = theme number, topics {placeholder}, question time limit 240 s, hint cost 20 / 40.
-- A test (b17_fresh.upgrade.mjs) installs both ways and fails if any structural column differs.
--
-- What it never touches: any team, member, session, team_themes / team_questions / answer_drafts / submissions row, coin balance,
-- ledger entry, timer, hint purchase, final score, penalty, or any price/duration/ordering column of an existing row (unlock_cost,
-- hints.cost, buy-time options, time_limit_seconds, difficulty, topics, ids). approve_submission and every other function are
-- unchanged: approval already pays exactly questions.reward_coins once (ledger index ctx_reward), so rewards are data.
--
-- Safe to re-run: only rows whose content differs are updated; a second run changes nothing and writes no audit row. An UPGRADE writes one
-- CONTENT_IMPORTED audit event (mode 'updated'); the first install into an empty database writes none (a fresh database has an empty audit log).
-- Submissions already approved keep the reward_awarded they were paid; a submission still PENDING when this runs is paid the NEW
-- reward of its question when it is approved. Apply it before the competition opens, or when no review is pending.

do $c26_import$
declare
  v_themes    int;
  v_questions int;
  v_hints     int;
  n_themes    int;
  n_questions int;
  n_hints     int;
  v_mode      text;
begin
  select count(*) into v_themes from themes;
  select count(*) into v_questions from questions;
  select count(*) into v_hints from hints;

  if not ((v_themes = 0 and v_questions = 0 and v_hints = 0) or (v_themes = 10 and v_questions = 50 and v_hints = 100)) then
    raise exception 'official content: expected 10 themes, 50 questions and 100 hints, found %, % and % (an empty database is also accepted)',
      v_themes, v_questions, v_hints;
  end if;

  -- the official content, once, for both paths
  create temp table c26_themes (id smallint primary key, name text not null, description text not null) on commit drop;
  create temp table c26_questions (id smallint primary key, body_md text not null, reward_coins int not null) on commit drop;
  create temp table c26_hints (id smallint primary key, body_md text not null) on commit drop;

  insert into c26_themes (id, name, description) values
    (1, $c26$DIG INTO THE PASSWORD OF IIT ISM$c26$, $c26$ADVANCED CRYPTOGRAPHY, NUMBER THEORY & COMBINATORICS$c26$),
    (2, $c26$HOW BAD CAN BE HOSTEL FOOD$c26$, $c26$PROBABILITY, STATISTICS, OPTIMIZATION AND QUEUING THEORY$c26$),
    (3, $c26$END SEM FEAR TAKEOVER$c26$, $c26$Engineering Mathematics, Calculus, and Differential Equations$c26$),
    (4, $c26$WHAT IS THE SIZE OF THE CAMPUS?$c26$, $c26$Geometry, Distance and Measurement, and Coordinate Geometry$c26$),
    (5, $c26$WHO IS THE POKER GUY HERE$c26$, $c26$Probability, Combinatorics, Game Theory, and Derangements$c26$),
    (6, $c26$ASK OUT YOUR CRUSH$c26$, $c26$PROBABILITY AND STATISTICS$c26$),
    (7, $c26$I WANT A STRAIGHT TRAJECTORY IN LIFE$c26$, $c26$Linear Systems, Geometry, Infinite Products, and Integrals$c26$),
    (8, $c26$IS THE GUARD CHASING YOU?$c26$, $c26$Coordinate Geometry, Conics, Vectors, and Relative Motion$c26$),
    (9, $c26$WHAT AMOUNT TO PUT IN PAY REQUEST TO MY SENIORS$c26$, $c26$Probability, Optimization, Geometric Distributions, and Game Theory$c26$),
    (10, $c26$DO YOU HATE PROVING YOURSELF?$c26$, $c26$Mathematical proofs, logic, induction, and contradiction$c26$);

  insert into c26_questions (id, body_md, reward_coins) values
    (1, $c26$A message intercepted from the campus network has been encoded in two steps. First, remove all spaces and punctuation from the plaintext, convert each letter to a number using A = 0, B = 1, …, Z = 25, and replace each value x by (x + 7) mod 26. Then reverse the order of the resulting letters.
The intercepted ciphertext is:
    PHOHOHYHHHGHTBFR

Recover the original message and write it in uppercase with the original word spacing restored.$c26$, 100),
    (2, $c26$A client and server use a small demonstration setup to recover a session token.

Part A: Diffie–Hellman
The server’s public value is B = 8, the client’s private exponent is a = 6, and the prime modulus is p = 23. Compute the shared value K = B^a mod p.

Part B: RSA decryption
The RSA modulus is N = 55 and the private exponent is d = 27. The intercepted ciphertext is C = 12. Compute the recovered token T = C^d mod N.

Give your final answer as two comma-separated integers: K,T.$c26$, 100),
    (3, $c26$A critical network router processes an array of N = 12 data packets. Due to buffer limits, the router can drop packets, but it cannot drop two consecutive packets (i.e., in a binary status sequence of length N where 1 = processed and 0 = dropped, the pattern '00' is forbidden).

Tasks:
1. Define the dynamic programming state transitions dp[i][0] (number of valid sequences of length i ending in 0) and dp[i][1] (ending in 1).
2. Derive the unified scalar recurrence relation f(n) for total valid configurations of length n.
3. Compute f(12) step-by-step from base cases f(0) and f(1).
4. If the constraint is modified such that no three consecutive packets can be dropped (forbidden pattern '000'), derive the new linear recurrence relation and compute the number of valid sequences for N = 6.$c26$, 100),
    (4, $c26$An array A of size N = 1000 represents millisecond network delay spikes generated by:

    A[i] = (i^2 + 3*i) (mod 50)   for 1 <= i <= 1000

A sequence of contiguous packets A[i...j] (1 <= i <= j <= 1000) causes buffer overflow if its sum is evenly divisible by S = 2008.

Tasks:
1. Define the prefix sum sequence P[m] = sum_{k=1}^m A[k] with P[0] = 0. Show why the condition sum_{k=i}^j A[k] = 0 (mod S) is logically equivalent to P[j] = P[i-1] (mod S).
2. Let C_r be the frequency of index m in [0, 1000] such that P[m] = r (mod S). Express the total number of valid contiguous subarrays W as a combinatorial summation over C_r.
3. Explain why this approach reduces time complexity from O(N^2) brute force to O(N + S), detailing how combination pairs C(C_r, 2) count disjoint index intervals.$c26$, 100),
    (5, $c26$A campus data center routes traffic from n = 6 input lines {L1, L2, L3, L4, L5, L6} to n = 6 output ports {P1, P2, P3, P4, P5, P6} such that each line maps to a distinct port (a permutation pi in S6).

To prevent hardware feedback loops, the mapping has the following positional restrictions:
  • Standard Derangement: Line Li cannot map to Port Pi for all 1 <= i <= 6 (pi(i) != i).
  • Additional Firewalls: Line L1 cannot map to Port P2 (pi(1) != 2), and Line L2 cannot map to Port P3 (pi(2) != 3).

Tasks:
1. State the Principle of Inclusion-Exclusion (PIE) formula for counting permutations with forbidden positions.
2. Define the set of forbidden condition properties A = {r1, r2, r3, r4, r5, r6, r7, r8}, where r1...r6 correspond to pi(i) = i, r7 corresponds to pi(1) = 2, and r8 corresponds to pi(2) = 3.
3. Determine the number of valid non-conflicting routing configurations by evaluating the intersection sizes |A_i1 cap A_i2 cap ... cap A_ik|.$c26$, 100),
    (6, $c26$The hostel mess has one serving counter. Students arrive according to a Poisson process at 20 students per hour. A fast plate takes exactly 1 minute and is chosen with probability q; a full thali takes exactly 3 minutes and is chosen with probability 1 − q. The cook currently uses q = 0.5. Find the mean time, in minutes, that a student waits in the queue, excluding service, in steady state.$c26$, 70),
    (7, $c26$Using q = 0.5, find the expected sum of the queue-waiting times of all students served during one busy period. A busy period begins when a student arrives at an empty counter and ends when the counter next becomes empty.$c26$, 70),
    (8, $c26$The warden defines the dissatisfaction cost per student as D(q) = Wq(q) + 4q, where the 4q term penalizes complaints about the fast plate being “just dal-rice.” The cook may choose any q in (0, 1], with the arrival rate unchanged. Find the total reduction in dissatisfaction per hour when the cook changes from q = 0.5 to the optimal q.$c26$, 90),
    (9, $c26$Each dinner is independently bad with probability 1/3 and good with probability 2/3. Find the expected number of days until the pattern bad, good, bad (B-G-B) appears for the first time as three consecutive dinners.$c26$, 60),
    (10, $c26$The mess committee surveys satisfaction scores in two hostels using stratified sampling. Hostel A has student share Wₐ = 0.4, standard deviation Sₐ = 5, and interview cost ₹1. Hostel B has student share Wᵦ = 0.6, standard deviation Sᵦ = 5, and interview cost ₹4. With a total budget of ₹256 and ignoring finite population correction, find the minimum possible variance of the weighted-mean estimator.$c26$, 100),
    (11, $c26$For each positive integer n, let Pₙ = ∏ₖ₌₁ⁿ(1 + tan(kπ/(4n))). Define I = limₙ→∞ (π/(4n)) ln Pₙ. Find a = 64I/(π ln 2).$c26$, 70),
    (12, $c26$Using the value of a from Q3.1, find b = Σₙ₌₁^∞ n^(a/2)/2ⁿ.$c26$, 80),
    (13, $c26$Find c = (120/(11e)) limₓ→₀ [((1 + x)^(1/x) − e + ex/2)/x²].$c26$, 80),
    (14, $c26$Let M be a c × c matrix whose entries are mᵢⱼ = |i − j|. Find d = det(M), using the value of c obtained in QC.3.$c26$, 90),
    (15, $c26$Evaluate L = limₙ→∞ n ∫₀¹ xⁿ(x² + 2)e^(x²) dx. Find L/e.$c26$, 90),
    (16, $c26$On Independence Day, a flagpole is tilted. Its line is given by (x+1)/0 = (y−2)/4 = z/3. Find the angle through which it must be rotated about the z-axis to make it vertical.$c26$, 100),
    (17, $c26$A bank near the heritage building is at (−13, −14, 0). The straightened pole-plus-flag is 15 m long. Assume the point (−1, 2, 0) on the pole’s line is at ground level, and the pole’s direction vector is (0, 4, 3). Find the equation of the line of sight from the bank to the top of the pole.$c26$, 60),
    (18, $c26$The oval garden near the heritage building is elliptical, centred at the origin. Its semi-major axis is 25 m along the x-axis and its semi-minor axis is 15 m along the y-axis. A coach standing at (30, 12, 0) kicks a football in a straight line parallel to the negative x-axis. The football travels until it reaches the boundary of the garden. Find the coordinates of the point where the football reaches the garden boundary.$c26$, 90),
    (19, $c26$Using the stopping point obtained in Q4.3, find its eccentric angle θ on the ellipse.$c26$, 50),
    (20, $c26$Find the distance between the centre of the ellipse and the stopping point from Q4.3. Treat this distance as the radius of a circular sector with central angle 30°. Find the sector area to 2 decimal places.$c26$, 90),
    (21, $c26$You are dealt 2 hole cards from a fresh 52-card deck. Let the probability that you are dealt a pocket pair be represented as a reduced fraction p/q. Find the value of q − p.$c26$, 70),
    (22, $c26$You are dealt 2 hole cards from a fresh 52-card deck. Let the probability that both your hole cards belong to the exact same suit be represented as a reduced fraction p/q. Find the value of p + q.$c26$, 80),
    (23, $c26$Two poker players, A and B, play a simplified zero-sum betting game. Player A chooses Bluff (B) or Play Safe (S), while Player B simultaneously chooses Call (C) or Fold (F). The payoff matrix gives Player A’s net payoff in coins; Player B receives the negative of this payoff.

                         Player B
                   Call (C)     Fold (F)
Player A  Bluff (B)      −4           6
          Play Safe (S)   3          −2

Both players may use mixed strategies. Let p be the probability that Player A bluffs and q be the probability that Player B calls. Find 300(p + q) when both players use optimal mixed strategies.$c26$, 90),
    (24, $c26$You hold Pocket Aces (A OF SPADES, A OF HEARTS). There are two opponents left to act behind you, and each receives 2 random hole cards. Let the probability that at least one of these two opponents is dealt a pocket pair of Aces or Kings be represented as a reduced fraction p/q. Find the value of p + q.$c26$, 60),
    (25, $c26$At a showdown, four unique cards of completely distinct ranks—an Ace, King, Queen, and Jack—are left exposed on the table. The dealer collects these 4 specific cards, shuffles them thoroughly, and redistributes them randomly into 4 distinct positions face-down on the table (Position 1 for Ace, Position 2 for King, Position 3 for Queen, Position 4 for Jack). If the probability that none of the 4 cards ends up back in its original designated position is expressed as a reduced fraction p/q, find the value of p + q.$c26$, 100),
    (26, $c26$To talk to your crush during a lecture, you sit in a row containing 15 seats. You place items on S seats to guarantee that no matter which unoccupied seat your crush chooses, they are forced to sit directly adjacent to at least one of your items. If S is the minimum number of seats needed, and P is the integer formed by concatenating your chosen 1-indexed seat positions in ascending order, what is P?$c26$, 70),
    (27, $c26$Using S = 5 from Question 1, you analyze your crush’s 10S + 1 = 51 friends who belong to K distinct campus clubs. What is the minimum value K_min such that you can guarantee at least two clubs have the exact same number of friends?$c26$, 70),
    (28, $c26$Using K = 11 from Question 2, you and your crush independently select 3 distinct days from an 11-day campus festival schedule. The probability that your selected schedules overlap on at least 2 days is an irreducible fraction a/b. Find a + b.$c26$, 90),
    (29, $c26$At your meet-up on day a + b of the semester, you order coffee together. Customers arrive at the café according to a Poisson process at an average rate λ = a + b per hour. If X is the number of arrivals in a 1-hour span, find E[X²].$c26$, 90),
    (30, $c26$Your crush presents a statistical challenge to deliver their final response. Their response score Y follows a Normal distribution N(μ, σ²), with mean μ equal to the answer from Question 4 and variance σ² = 2500 (so σ = 50). If P(Y ≤ y) = 0.9772 and the standard normal CDF satisfies Φ(2) = 0.9772, find y.$c26$, 100),
    (31, $c26$A vector-valued function w(t) satisfies w′(t) = Xw(t), where X = [[0, −2], [1/2, 0]] and w(0) = (2, 0). Find the maximum value of ‖w(t + π/2) − w(t)‖² over all real t.$c26$, 80),
    (32, $c26$The trajectory from Q8.1 traces an ellipse. Take the four points at times T, T + π/2, T + π, and T + 3π/2, and join them in order to form a quadrilateral. Using the ellipse enclosed by the trajectory as the reference shape, find the percentage of the ellipse’s area missed by the quadrilateral, rounded down to the nearest integer. (The result is independent of T.)$c26$, 90),
    (33, $c26$Evaluate the infinite product ∏ from n = 2 to ∞ of (n³ − 1)/(n³ + 1). Express your answer as a reduced fraction.$c26$, 90),
    (34, $c26$Evaluate the improper integral ∫ from 0 to 1 of ln(1 − x)/x dx.$c26$, 50),
    (35, $c26$Let F(x, y, z) = ln(1 − xyz)/(xyz), interpreted by continuity wherever xyz = 0. Evaluate the triple integral of F over the unit cube 0 ≤ x, y, z ≤ 1. If the result is written as −ζ(n), find n.$c26$, 100),
    (36, $c26$A circular zone is given by x² + y² = 16, and an escape parabola is given by y² = 16√2 x. The guard starts at the topmost point of the circle and moves anticlockwise along the circle to the point where the common tangent with positive slope to the circle and parabola touches the circle. He then follows this tangent to the portal on the parabola. Find the total distance travelled along the circular arc and then along the tangent. If the distance is aπ + b, enter a + b. Portal transit time: 1.5 seconds to enter and 1.5 seconds to exit.$c26$, 70),
    (37, $c26$The portal leads to an elliptical chamber given by (x − 17)²/25 + (y − 96/5)²/16 = 1. The guard appears at the lower endpoint of the right latus rectum of the ellipse. The runner is at the bottommost point of the original circle from Q9.1. At this instant, the guard moves with velocity v_G = −3i − 4j m/s and the runner moves with velocity v_R = −i − 2j m/s. Find the area of the triangle formed by the runner’s initial position, the guard’s initial position, and their meeting point.$c26$, 90),
    (38, $c26$The guard moves around the original circle with angular velocity π/2 rad/s anticlockwise and travels along the common tangent at 1 m/s. The portal takes 1.5 seconds to enter and 1.5 seconds to exit. Assume the runner remains at the bottommost point of the original circle until the guard exits the portal. After the guard exits, both move with the velocities given in Q9.2. Using the results from the previous questions, find the total time in seconds from the beginning of the chase until the guard catches the runner.$c26$, 90),
    (39, $c26$The guard is initially at G = (0, 0) and can run at a constant speed of 13 m/s in any direction. The runner is initially at R = (30, 0) and moves with velocity v_R = −5i + 12j m/s. After how many seconds will the guard catch the runner?$c26$, 90),
    (40, $c26$A circular security barrier is given by (x − 5)² + (y + 2)² = 169. The guard stands at G = (20, −7), outside the barrier. He fires a straight tracking beam along the line 3x + 4y = 32. The beam enters the circular barrier at one point and exits at another. Find the distance between the entry and exit points.$c26$, 100),
    (41, $c26$Senior i accepts a request of ₹x with probability 1 − x/kᵢ, independently, where (k₁, k₂, k₃, k₄) = (150, 200, 250, 300) for A, B, C, D. You send ₹50 to each of them. Given that exactly two accepted, what is the probability that A is one of the two?$c26$, 90),
    (42, $c26$You request ₹x₁, ₹x₂, ₹x₃, ₹x₄ from A, B, C, D with x₁ + x₂ + x₃ + x₄ = 500 and 0 ≤ xᵢ ≤ kᵢ. Senior i accepts independently with probability 1 − xᵢ/kᵢ, where (k₁, k₂, k₃, k₄) = (150, 200, 250, 300) (a larger kᵢ means a richer senior, who tolerates larger requests). Find the maximum possible expected total receipt.$c26$, 100),
    (43, $c26$Each day, A, B, C, D independently call you with probabilities 1/2, 1/3, 1/4, 1/5, independently across days. What is the probability that the first day on which you get at least one call is an odd-numbered day?$c26$, 80),
    (44, $c26$A, B, C, D independently ask you to run an errand with probabilities 1/2, 1/2, 3/4, 3/4, and the errands take 10, 20, 30, 40 minutes respectively. Let X be the total time spent on errands in a day. Find P(X ≥ 60).$c26$, 80),
    (45, $c26$To settle your pay requests, the seniors put 14 ₹10 notes into three labelled envelopes (a, b, c), none empty, so (1,6,7) and (6,1,7) are different splits. You and a senior take turns removing any number of notes from one envelope, and whoever takes the last note wins the pay request off the table. You move second and both play optimally. If you win for exactly k of the possible splits, shift each letter of EJKNN JCK forward by k places (Z wraps to A). With A = 1, B = 2, …, Z = 26, find the sum of the alphabet positions of all letters in the decoded message.$c26$, 100),
    (46, $c26$Person k (k = 1, 2, …, 2026) says: “Exactly k of the 2026 people here are liars.” Truth-tellers always tell the truth and liars always lie. Find the sum of the labels of all truth-tellers.$c26$, 80),
    (47, $c26$2025 people sit around a circular table. Each is either a truth-teller (always true) or a liar (always false). Every person says: “My two neighbours are of different types.” What is the maximum possible number of truth-tellers?$c26$, 90),
    (48, $c26$Three students each claim a statement holds for all positive integers n:
Alice: n² + n + 41 is prime (she also allows n = 0).
Bob: 2ⁿ ≥ n².
Carol: n³ + 2n is divisible by 3.
Let A be the smallest n where Alice’s claim fails and B the smallest n where Bob’s claim fails. Find A + B. (If Carol’s claim fails, add 1000. Otherwise add nothing.)$c26$, 70),
    (49, $c26$Josephus Problem
• n people stand in a circle, numbered from 1 to n in a clockwise direction.
• Starting from person 1, you count around the circle and eliminate every k-th person.
• The circle shrinks as people are removed, and counting continues from the next living person.
• This process repeats until only one person remains—the goal is to find the starting position of that last survivor.
There are 50 soldiers in a circle, ranked 1 to 50. Soldier 1 jumps first, then every alternate remaining soldier jumps. What is the rank of the last soldier?$c26$, 90),
    (50, $c26$The last surviving soldier has rank 45. What is the smallest number of soldiers that could have been on the ship?$c26$, 90);

  insert into c26_hints (id, body_md) values
    (1, $c26$REVERSE THE PIPELINE: The last encryption step was reversing the entire string, so undo that step first. Then undo the letter-number transformation.$c26$),
    (2, $c26$MODULAR SHIFT: Convert each ciphertext letter to A = 0, …, Z = 25. To reverse x ↦ (x + 7) mod 26, compute (x − 7) mod 26 for every letter. Restore the spaces using the familiar phrase.$c26$),
    (3, $c26$REPEATED SQUARING: For Part A, calculate B² and B⁴ modulo p, then combine them to obtain B⁶. Reduce modulo p after each multiplication.$c26$),
    (4, $c26$RSA MODULAR EXPONENTIATION: For Part B, use the binary expansion of 27 = 16 + 8 + 2 + 1. Repeatedly square 12 modulo 55 and multiply the powers corresponding to those exponents, reducing modulo 55 each time.$c26$),
    (5, $c26$SPLIT BY THE LAST BIT: For strings that forbid '00', count valid strings ending in 1 separately from those ending in 0. A string ending in 0 must have a 1 immediately before it, so remove the final 10 and count the valid prefix that remains.$c26$),
    (6, $c26$GENERALIZE TO THREE ZEROS: When '000' is forbidden, every valid string must end in one of the suffixes 1, 10, or 100 (apart from short base cases). Removing those suffixes gives a three-term recurrence. Establish values for lengths 0, 1, and 2 before computing the requested totals.$c26$),
    (7, $c26$PREFIX-SUM DIFFERENCE: Let P[m] be the sum of the first m array entries. A subarray from i to j has sum P[j] − P[i−1]. It is divisible by 2008 exactly when those two prefix sums have the same remainder modulo 2008.$c26$),
    (8, $c26$COUNT MATCHING REMAINDERS: Build the frequencies Cᵣ of all 1001 prefix-sum remainders, including P[0]. If a remainder appears Cᵣ times, choose any two of those indices to form a valid subarray, giving C(Cᵣ, 2) = Cᵣ(Cᵣ − 1)/2. Sum over all remainders; this avoids checking every pair of array endpoints.$c26$),
    (9, $c26$FORBIDDEN-CELL BOARD: Represent a permutation as a 6 × 6 board with one selected cell in every row and column. The six diagonal cells are forbidden, and the extra firewall rules forbid (1, 2) and (2, 3). The desired count can be obtained by inclusion–exclusion over these eight forbidden cells.$c26$),
    (10, $c26$ROOK NUMBERS & INCLUSION–EXCLUSION: Let rₖ be the number of ways to place k non-attacking rooks on the eight forbidden cells. Then the number of valid permutations is Σₖ₌₀⁶ (−1)ᵏ rₖ(6 − k)!. Count the rₖ by selecting forbidden cells with no shared row or column, then substitute into the sum.$c26$),
    (11, $c26$TOPIC: This problem uses M/G/1 queueing theory. Calculate the server’s utilization and account for variability in service time.$c26$),
    (12, $c26$FORMULA: Use the Pollaczek–Khinchine formula: Wq = λE[S²] / [2(1 − ρ)], where λ is the arrival rate and ρ = λE[S].$c26$),
    (13, $c26$TOPIC: This problem involves busy-period analysis and regenerative processes in queueing theory. A busy period lasts from the first arrival to an empty counter until the counter becomes empty again.$c26$),
    (14, $c26$FORMULA: For an M/G/1 queue, the expected busy-period duration is E[B] = E[S] / (1 − ρ). Little’s law gives Lq = λWq. Use these relationships carefully to determine the expected accumulated queue area during a busy period$c26$),
    (15, $c26$HINT 1 — TOPIC: This problem combines queueing theory and differential calculus. Express dissatisfaction as a function of the probability of choosing the fast plate, then minimize it.$c26$),
    (16, $c26$HINT 2 — FORMULA: For a differentiable objective D(q), find an interior minimum by solving dD(q)/dq = 0. Compare dissatisfaction before and after optimization, then multiply the per-student reduction by the arrival rate.$c26$),
    (17, $c26$TOPIC: This problem uses probability, state transitions, and first-step analysis. Track how much of the target sequence has been matched by the most recent dinners.$c26$),
    (18, $c26$FORMULA: Use the first-step expectation equation Eᵢ = 1 + Σⱼ pᵢⱼEⱼ, where Eᵢ is the expected number of additional dinners from state i and pᵢⱼ is the probability of moving from state i to state j. The completed-pattern state has expected additional waiting time zero.$c26$),
    (19, $c26$TOPIC: This problem involves stratified sampling and constrained optimization. The hostels have different population weights and interview costs, so equal sample sizes may not be optimal.$c26$),
    (20, $c26$FORMULA: The variance is V(ȳ) = Σₕ(Wₕ²Sₕ²/nₕ). For minimum variance with unequal sampling costs, use the cost-optimal allocation nₕ ∝ WₕSₕ/√cₕ, together with the total budget constraint.$c26$),
    (21, $c26$— TOPIC: A sum of function values multiplied by a shrinking interval width can converge to a definite integral; this is a Riemann sum.$c26$),
    (22, $c26$FORMULA: Once you obtain the integral, use the symmetry property of definite integrals known as King’s property.$c26$),
    (23, $c26$TOPIC: An infinite series involving powers of n can sometimes be generated by repeatedly differentiating a simpler power series.$c26$),
    (24, $c26$FORMULA: Start with Σₙ₌₁^∞ xⁿ = x/(1 − x). Differentiate until the required power of n appears, then substitute x = 1/2.$c26$),
    (25, $c26$TOPIC: When constant and linear terms cancel, a second-order expansion determines the limit.$c26$),
    (26, $c26$FORMULA: Use JEE expansions of ln(1 + x) and eˣ, retaining terms through order x².$c26$),
    (27, $c26$TOPIC: Matrix entries depend on the distance between indices; exploit the structure rather than expanding the determinant directly.$c26$),
    (28, $c26$FORMULA: Use determinant-preserving elementary operations: subtract consecutive rows, then consecutive columns, to create zeros.$c26$),
    (29, $c26$TOPIC: As n grows, xⁿ is negligible for most of [0, 1], while values near x = 1 dominate.$c26$),
    (30, $c26$FORMULA: Try t = xⁿ. After substitution use t^(1/n) → 1 for 0 < t ≤ 1, and evaluate the resulting integral carefully.$c26$),
    (31, $c26$TOPIC: A line in 3D space has a direction vector. Think about what rotating a line around the z-axis changes—and what it leaves unchanged.$c26$),
    (32, $c26$FORMULA/METHOD: The direction vector is (0, 4, 3). A rotation about the z-axis preserves the z-component and the magnitude of the horizontal component. Can the resulting direction become parallel to the z-axis?$c26$),
    (33, $c26$TOPIC: To locate the top of the pole, convert its direction vector into a unit vector first. Then use the pole’s length to calculate the displacement from its base.$c26$),
    (34, $c26$FORMULA/METHOD: For direction vector v and pole length L, the displacement is d = L(v/|v|). Add this displacement to the base point to find the top. Then form the line passing through the bank and the top of the pole.$c26$),
    (35, $c26$TOPIC: The boundary of an elliptical garden is described by an equation relating the x- and y-coordinates. Since the ball travels parallel to the negative x-axis, one coordinate stays constant throughout its path.$c26$),
    (36, $c26$FORMULA/METHOD: Use x²/25² + y²/15² = 1. The ball starts at (30, 12, 0), and its y-coordinate remains 12. Substitute y = 12, solve for x, and choose the first boundary point reached while moving in the negative x-direction.$c26$),
    (37, $c26$TOPIC: An ellipse can be parameterized using an angle called the eccentric angle. The x- and y-coordinates are scaled by different semi-axes.$c26$),
    (38, $c26$FORMULA/METHOD: Use x = a cos θ and y = b sin θ, where a = 25 and b = 15. Substitute the stopping point from Q4.3, find cos θ and sin θ, and choose the angle in the correct quadrant.$c26$),
    (39, $c26$TOPIC: The distance from the ellipse’s centre to the stopping point is the radius of the circular sector. Use the distance formula before calculating the area.$c26$),
    (40, $c26$FORMULA/METHOD: For a point (x, y) measured from the origin, r = √(x² + y²). The area of a sector with angle α in degrees is A = (α/360°)πr². Use the stopping point from Q4.3 and α = 30°.$c26$),
    (41, $c26$TOPIC: Think of the two cards as a sequence of draws. The first card can be any card, so focus on what the first draw tells you about the second.$c26$),
    (42, $c26$METHOD: Once the first card is known, count how many of the remaining cards share its rank, out of the total number of cards left in the deck.$c26$),
    (43, $c26$TOPIC: The first card establishes a suit. Consider which property of that card must match for the two cards to be suited.$c26$),
    (44, $c26$METHOD: Each suit contains 13 cards. After drawing the first card, count how many cards of that same suit remain among the undealt cards.$c26$),
    (45, $c26$TOPIC: In a zero-sum game, an optimal mixed strategy makes the opponent indifferent between the actions they choose with positive probability.$c26$),
    (46, $c26$METHOD: Find p by equating Player B’s expected payoffs from Call and Fold. Find q by equating Player A’s expected payoffs from Bluff and Play Safe. Solve the two equations, then calculate 300(p + q).$c26$),
    (47, $c26$TOPIC: Define one event for each opponent receiving a pocket pair of Aces or Kings. Find each event’s probability separately before combining them.$c26$),
    (48, $c26$METHOD: Apply inclusion–exclusion: P(E₁ ∪ E₂) = P(E₁) + P(E₂) − P(E₁ ∩ E₂). For the intersection, count the ways both opponents can receive valid target pairs, remembering that their hands must be disjoint.$c26$),
    (49, $c26$TOPIC: This is a permutation problem in which every card must end up in a position different from its original one.$c26$),
    (50, $c26$FORMULA: Use the derangement formula Dₙ = n! Σₖ₌₀ⁿ (−1)ᵏ/k!. Count the valid arrangements for four cards, then divide by the total number of possible arrangements.$c26$),
    (51, $c26$LOGIC: An item can make its own seat and its immediate neighbours unavailable. First find an upper bound on how many seats one item can cover, then show a placement that covers the entire row.$c26$),
    (52, $c26$FORMULA/METHOD: Each item covers at most 3 seats, so at least ceil(15/3) items are needed. Check a construction such as positions 2, 5, 8, 11, 14, and verify that every seat is either occupied or adjacent to an item.$c26$),
    (53, $c26$LOGIC: To avoid a tie, every club must have a different non-negative number of members. What is the smallest possible total if K clubs have distinct sizes?$c26$),
    (54, $c26$FORMULA/METHOD: The minimum sum of K distinct non-negative integers is 0 + 1 + ... + (K − 1) = K(K − 1)/2. Find the smallest K for which K(K − 1)/2 > 51.$c26$),
    (55, $c26$LOGIC: Fix your own 3-day selection. Count the other person’s selections that share exactly 2 days, then add the case where all 3 days match.$c26$),
    (56, $c26$FORMULA/METHOD: Total selections are C(11, 3). Exactly 2 shared days: C(3, 2)C(8, 1); exactly 3 shared days: C(3, 3)C(8, 0). Add the favourable counts, form the probability, and reduce the fraction.$c26$),
    (57, $c26$LOGIC: For a Poisson random variable, the mean and variance are both equal to its rate parameter. The question asks for the second moment, not just the mean.$c26$),
    (58, $c26$FORMULA/METHOD: Use Var(X) = E[X²] − (E[X])² and E[X] = Var(X) = λ. Rearrange to obtain E[X²] = λ + λ², then substitute the value from Question 3.$c26$),
    (59, $c26$LOGIC: Convert the score into a standard normal variable. The given cumulative probability tells you which standard-normal quantile to use.$c26$),
    (60, $c26$FORMULA/METHOD: Use Z = (Y − μ)/σ. Set (y − μ)/50 = 2, then solve for y using the mean obtained in Question 4$c26$),
    (61, $c26$TOPIC/LOGIC: The key is to understand what happens when the matrix X is applied twice. This can simplify the differential equation into familiar sine and cosine functions.$c26$),
    (62, $c26$METHOD/FORMULA: Calculate X² first, then use w(t) = e^(tX)w(0) to derive w(t). Evaluate w(t + π/2), subtract w(t), and maximize the resulting trigonometric expression.$c26$),
    (63, $c26$TOPIC/LOGIC: Use the geometry of the ellipse and the quadrilateral formed by four equally spaced trajectory points. The percentage error compares their enclosed areas.$c26$),
    (64, $c26$METHOD/FORMULA: The ellipse has semi-axes a and b, so its area is πab. Find the quadrilateral’s area from its vertices, then compute floor(100 × (ellipse area − quadrilateral area)/(ellipse area)).$c26$),
    (65, $c26$TOPIC/LOGIC: Factor the numerator and denominator as sums or differences of cubes. Look for cancellation between neighbouring factors after reindexing.$c26$),
    (66, $c26$METHOD/FORMULA: Use n³ − 1 = (n − 1)(n² + n + 1) and n³ + 1 = (n + 1)(n² − n + 1). Write the partial product through n = N, reindex the quadratic factors where possible, and take the limit as N tends to infinity.$c26$),
    (67, $c26$TOPIC/LOGIC: Expand the logarithm as a power series on 0 ≤ x < 1, then integrate the resulting terms.$c26$),
    (68, $c26$METHOD/FORMULA: Use ln(1 − x) = −∑ from n = 1 to ∞ of xⁿ/n. After dividing by x and integrating term-by-term, connect the result to the Basel sum ∑1/n².$c26$),
    (69, $c26$TOPIC/LOGIC: Use the power-series expansion of ln(1 − u)/u, with u = xyz. The product structure lets the triple integral separate into three one-dimensional integrals.$c26$),
    (70, $c26$METHOD/FORMULA: For |u| < 1, ln(1 − u)/u = −∑ from k = 1 to ∞ of u^(k−1)/k. Integrate each term over x, y, and z; each one-dimensional integral contributes a factor 1/k. Compare the resulting series with ζ(n).$c26$),
    (71, $c26$TOPIC/LOGIC: This combines a circle and a parabola. Find their common tangent, then distinguish the circle’s tangency point from the parabola’s tangency point.$c26$),
    (72, $c26$METHOD/FORMULA: For the circle x² + y² = r², a tangent with slope m can be written y = mx ± r√(1 + m²). For the parabola y² = 4ax, use its tangent form y = mx + a/m. Match the line and identify both contact points; then use arc length rθ and the distance formula.$c26$),
    (73, $c26$TOPIC/LOGIC: First determine the two initial positions. Then use relative motion: a meeting occurs when the relative position can be eliminated by the relative velocity after the same elapsed time.$c26$),
    (74, $c26$METHOD/FORMULA: Write G(t) = G₀ + v_G t and R(t) = R₀ + v_R t. Set their x-coordinates equal to find t, then verify that the y-coordinates agree. Find the meeting point and use A = ½|x₁(y₂−y₃) + x₂(y₃−y₁) + x₃(y₁−y₂)|.$c26$),
    (75, $c26$TOPIC/LOGIC: Separate the timeline into the circular arc, tangent travel, portal transit, and post-portal chase. Add the durations only after calculating each one.$c26$),
    (76, $c26$METHOD/FORMULA: Use t = θ/ω for the circular arc, t = distance/speed for the tangent, add both portal delays, and then add the meeting time from Q9.2.$c26$),
    (77, $c26$TOPIC/LOGIC: At the instant of interception, the guard must be able to reach the runner’s position in the same elapsed time. Use the runner’s position as a function of time.$c26$),
    (78, $c26$METHOD/FORMULA: After t seconds, the runner is at (30 − 5t, 12t), while the guard’s maximum reachable distance is 13t. Set (30 − 5t)² + (12t)² = (13t)² and solve for the positive time.$c26$),
    (79, $c26$TOPIC/LOGIC: The entry and exit points are the endpoints of a chord of the circle. The perpendicular from the centre to a chord bisects the chord.$c26$),
    (80, $c26$METHOD/FORMULA: Find the circle’s centre and radius, then calculate the perpendicular distance d from the centre to 3x + 4y − 32 = 0 using d = |Ax₀ + By₀ + C|/√(A²+B²). The chord length is 2√(r² − d²).$c26$),
    (81, $c26$Start by finding each senior’s actual chance of accepting a ₹50 request. Then ask yourself: in how many different ways can exactly two of the four accept, and what is each way worth?$c26$),
    (82, $c26$Enumerate every way for exactly two to accept and work out its probability. Look closely at the numbers you get: is there any structure they share that makes comparing them easier? Remember that “given that” means you only look at the cases where exactly two accepted.$c26$),
    (83, $c26$Write the expected receipt as a function of the four amounts. Once the total is fixed, how many of the amounts are really free to choose?$c26$),
    (84, $c26$Reduce to the free variables and look for the point where the expected receipt stops changing. What do the resulting conditions tell you about the ratios xᵢ/kᵢ? Before you finish, check that your amounts are allowed, and that you have found a maximum rather than a minimum.$c26$),
    (85, $c26$How likely is a day with no call at all? Now think about what must happen for the first call to come on day 1, on day 2, and on day 3.$c26$),
    (86, $c26$Write out the probabilities for the first few qualifying days as numbers. Do you notice how each one relates to the one before it? Think about how you would add up infinitely many terms with that kind of pattern.$c26$),
    (87, $c26$List every possible combination of who asks and who does not. How many are there, and how many minutes does each one cost you?$c26$),
    (88, $c26$Pick out the combinations that reach 60 minutes or more and add their probabilities. You may be able to save effort by grouping the combinations: which seniors’ choices matter most for reaching 60?$c26$),
    (89, $c26$Try playing small versions of this game (for example, piles such as (1,1,0), (1,2,3), (2,2,1)). Look for a pattern in the positions where the player to move loses. Writing the pile sizes in binary may help.$c26$),
    (90, $c26$Once you know exactly when the second player wins, go through the possible splits of 14 and test each one. Be careful when counting, because the envelopes are labelled. For the message, think about how to apply a shift of k to each letter, and what happens at the end of the alphabet.$c26$),
    (91, $c26$Compare any two people’s statements. Can both be true at the same time?$c26$),
    (92, $c26$So at most one person is truthful. Rule out “nobody is truthful” by asking what person 2026 would be saying in that case. With exactly one truth-teller, count the liars. Then find which person’s claim matches that count.$c26$),
    (93, $c26$Give each person a value, 1 for truth-teller and 0 for liar. Ask what a person’s own type must be, given what their neighbours’ types are. The rule is the same whether the speaker is honest or lying.$c26$),
    (94, $c26$Rearrange it to xᵢ₊₁ = xᵢ + xᵢ₋₁. Two consecutive values then fix the whole sequence, which repeats every 3 seats. Try the four possible starting pairs, and note that 3 divides 2025. Count how many 1s each block of 3 holds and take the best.$c26$),
    (95, $c26$Write Alice’s expression as n(n + 1) + 41. Ask when 41 could divide the whole thing, and what that would make the number. For Bob, just test n = 1, 2, 3, … until it breaks. For Carol, compare with the induction proof in Proposition 2.2 of the handbook.$c26$),
    (96, $c26$If 41 divides n(n + 1), then 41 divides the whole expression, so it isn’t prime (unless it equals 41 itself). The smallest n with 41 | n(n + 1) is the first place to check. The values for n = 0 to 39 are the well-known prime run. For Bob, compare 2ⁿ with n² at n = 1, 2, 3. Carol’s claim is exactly the statement proved in Proposition 2.2, so decide whether the 1000 is added.$c26$),
    (97, $c26$Simulate n = 1 to 8 by hand and write down the survivors. Notice when the survivor resets to 1 and how it changes between resets.$c26$),
    (98, $c26$J(n) = 2(n − 2^⌊log₂n⌋) + 1, where 2^⌊log₂n⌋ is the largest power of 2 not exceeding n.$c26$),
    (99, $c26$Simulate n = 1 to 8 by hand and write down the survivors. Notice when the survivor resets to 1 and how it changes between resets.$c26$),
    (100, $c26$J(n) = 2(n − 2^⌊log₂n⌋) + 1, where 2^⌊log₂n⌋ is the largest power of 2 not exceeding n.$c26$);

  if v_themes = 0 then
    v_mode := 'installed';

    insert into themes (id, code, name, description, topics, difficulty, unlock_cost, display_order)
    select c.id, chr(64 + c.id), c.name, c.description, array['placeholder'],
           (case when c.id <= 3 then 'EASY' when c.id <= 7 then 'MEDIUM' else 'HARD' end)::difficulty,
           100, c.id
      from c26_themes c;
    get diagnostics n_themes = row_count;

    insert into questions (id, theme_id, ordinal, body_md, difficulty, reward_coins, time_limit_seconds)
    select q.id, (q.id - 1) / 5 + 1, (q.id - 1) % 5 + 1, q.body_md, t.difficulty, q.reward_coins, 240
      from c26_questions q
      join themes t on t.id = (q.id - 1) / 5 + 1;
    get diagnostics n_questions = row_count;

    insert into hints (id, question_id, tier, body_md, cost)
    select h.id, (h.id + 1) / 2, (h.id - 1) % 2 + 1, h.body_md,
           case (h.id - 1) % 2 + 1 when 1 then 20 else 40 end
      from c26_hints h;
    get diagnostics n_hints = row_count;
  else
    v_mode := 'updated';

    update themes t
       set name = c.name, description = c.description
      from c26_themes c
     where t.id = c.id
       and (t.name, t.description) is distinct from (c.name, c.description);
    get diagnostics n_themes = row_count;

    update questions q
       set body_md = c.body_md, reward_coins = c.reward_coins
      from c26_questions c
     where q.id = c.id
       and (q.body_md, q.reward_coins) is distinct from (c.body_md, c.reward_coins);
    get diagnostics n_questions = row_count;

    update hints h
       set body_md = c.body_md
      from c26_hints c
     where h.id = c.id
       and h.body_md is distinct from c.body_md;
    get diagnostics n_hints = row_count;
  end if;

  -- whichever way it went, the database now holds exactly the official content
  if (select count(*) from themes t join c26_themes c using (id)
       where (t.name, t.description) = (c.name, c.description)) <> 10
     or (select count(*) from questions q join c26_questions c using (id)
          where (q.body_md, q.reward_coins) = (c.body_md, c.reward_coins)) <> 50
     or (select count(*) from hints h join c26_hints c using (id)
          where h.body_md = c.body_md) <> 100 then
    raise exception 'official content: the database does not hold the official content after the import';
  end if;

  -- an UPDATE of existing rows is an operational change and is audited; the first INSTALL into an empty database is the database's
  -- initial content (like the seed itself) and writes no audit row, so a freshly built database has an empty audit log
  if v_mode = 'updated' and n_themes + n_questions + n_hints > 0 then
    insert into audit_events (occurred_at, actor_kind, event_type, entity_type, entity_id, payload)
    values (clock_timestamp(), 'SYSTEM', 'CONTENT_IMPORTED', 'COMPETITION', '1',
            jsonb_build_object('mode', v_mode, 'themes_changed', n_themes, 'questions_changed', n_questions,
                               'hints_changed', n_hints, 'content_sha256', '1c2133dd052a901aa6c9eae4fc2b418fa33b55b55ad9ffa7b4a423b16d17dcdb'));
  end if;
  raise notice 'official content: % themes, % questions, % hints updated (%)', n_themes, n_questions, n_hints, v_mode;

  drop table c26_themes;
  drop table c26_questions;
  drop table c26_hints;
end $c26_import$;
